#define MOD 1000000007

long long binpow(long long a, long long k)
{
    long long ans = 1;
    if(a == 0) return 0;
    while(k)
    {
        if(k & 1) 
        {
            ans *= a;
            ans %= MOD;
        }
        a *= a;
        a %= MOD;
        k >>= 1;
    }
    return ans;
}

int main()
