int main() {
    ll k, n;
    scanf("%d%d", &n, &k);
    char s[105];
    scanf("%s", s);

    char next[105][30];   //next[i][c]: iから見て一番初めにc(+'a')が現れるindex
    for (int j = 0; j < 26; j++) next[n][j] = n;
    for (int i = n-1; i >= 0; i--) {
        for (int j = 0; j < 26; j++) next[i][j] = next[i+1][j];
        next[i][s[i]-'a'] = i;
    }

    ll dp[105][105] = {0};      //dp[i][l]: sのi文字目を接尾辞としてもつ，長さlの部分文字列の数
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 26; ++j) {
            if (next[i][j] >= n) continue;
            for (int l = 0; l < n; l++)
                dp[next[i][j] + 1][l+1] += dp[i][l];
        }
    }

    ll ans = 0, cnt = 0, tmp = 1;
    for (int j = n-1; j >= 0; j--) {
        for (int i = 0; i <= n; i++) {
            tmp += dp[i][j];
            if(tmp < k){                
                ans += (n-j)*dp[i][j];
            }else{
                ans += (n-j)*(k-(tmp-dp[i][j]));
                break;
            }
        }
        if(tmp >= k) break;
    }
    if(tmp < k) ans = -1;

    printf("%lld\n", ans);
}

