#include <stdio.h>

#define maxn 10001

const int mod = (int) 1e9 + 7;

long long choose[maxn][maxn];

long long f[maxn][maxn];
long long g[maxn][maxn];

long long power( long long a, long long b ) {
	long long ret = 1;

	a %= mod;
	while( b > 0 ) {
		if( b % 2 ) {
			ret = (ret * a) % mod;
		}

		b /= 2;
		a = (a * a) % mod;
	}

	return ret;
}

int main( void ) {
	long long n, m, k;
	scanf("%lld %lld %lld", &n, &m, &k);

	for( int i = 0; i < maxn; i++ ) {
		choose[i][0] = choose[i][i] = 1;
		for( int j = 1; j < i; j++ ) {
			choose[i][j] = (choose[i-1][j] + choose[i-1][j-1]) % mod;
		}
	}

	for( int i = 1; i <= n; i++ ) {
		for( int c = 0; c <= n; c++ ) {
			long long count = (m / n) + (m % n >= i ? 1 : 0);
			g[i][c] = power(choose[n][c], count);
		}
	}

	f[1][0] = 1;
	for( int i = 1; i <= n; i++ ) {
		for( int j = 0; j <= k; j++ ) if( f[i][j] > 0 ) {
			for( int c = 0; c <= n; c++ ) {
				if( j + c > k ) break;
				long long nways = (g[i][c] * f[i][j]) % mod;
				f[i+1][j+c] = (f[i+1][j+c] + nways) % mod;
			}
		}
	}

	printf("%lld\n", f[n+1][k]);

	return 0;
}

