#include <stdio.h>

int md;

long long power(int a, long long k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k / 2);
	p = p * p % md;
	if (k % 2)
		p = p * a % md;
	return p;
}

void mult(int aa[][2], int bb[][2], int cc[][2]) {
	int i, j, k;

	for (i = 0; i < 2; i++)
		for (j = 0; j < 2; j++) {
			long long c = 0;

			for (k = 0; k < 2; k++)
				c += (long long) aa[i][k] * bb[k][j];
			cc[i][j] = c % md;
		}
}

void power_(int aa[][2], int pp[][2], int tt[][2], long long k) {
	if (k == 0) {
		pp[0][0] = pp[1][1] = 1;
		pp[0][1] = pp[1][0] = 0;
		return;
	}
	if (k % 2 == 0) {
		power_(aa, tt, pp, k / 2);
		mult(tt, tt, pp);
	} else {
		power_(aa, pp, tt, k / 2);
		mult(pp, pp, tt);
		mult(tt, aa, pp);
	}
}

int main() {
	static int aa[2][2], pp[2][2], tt[2][2];
	long long n, k, x0, x1, ans;
	int l, h;

	scanf("%lld%lld%d%d", &n, &k, &l, &md);
	if (l < 64 && k >= 1LL << l) {
		printf("0\n");
		return 0;
	}
	aa[0][0] = 1, aa[0][1] = 1;
	aa[1][0] = 1, aa[1][1] = 0;
	power_(aa, pp, tt, n);
	x0 = (pp[0][0] + pp[0][1]) % md;
	x1 = (power(2, n) - x0 + md) % md;
	ans = 1 % md;
	for (h = 0; h < l; h++)
		ans = ans * ((k & 1LL << h) == 0 ? x0 : x1) % md;
	printf("%lld\n", ans);
	return 0;
}

