long long waysToPlay(int n, int m, int k) {
    // 6, 7, 2
    // 
    // 4, 4, 1 => 9
    // 6, 7, 2 => 75

    // If no more moves
    if (k == 0) {
        return 1;
    } else if (k == 1) {
        //printf("%d %d %d %lld\n", n, m, k, choose(n-1, 2) * choose(m-1, 2));
        return choose(n-1, 2) * choose(m-1, 2);
    } else {
        // For 5x5 (3x3)
        // Answer = 36
        // k = 1
        // x = 4c2
        // y = 4c2

        // 10 * 10 = 100

        // Smallest cases
        int n_small = 1 + 2*(k-1);
        int m_small = 1 + 2*(k-1);
        long long ways = 0;

        // They must be TWO less
        for (int n_i = n_small; n_i < n-1; n_i++) {
            for (int m_i = m_small; m_i < m-1; m_i++) {
                // The amount of positions that the new rectangle
                // can fit into
                int newMult = (n-n_i-1)*(m-m_i-1);

                // Cache the result
                if (known[m_i][n_i][k-1] == 0) {
                    known[m_i][n_i][k-1] = waysToPlay(n_i, m_i, k-1);
                }

                // Add it to ways
                ways += newMult * known[m_i][n_i][k-1];
            }
        }

        //printf("%d %d %d %lld\n", n, m, k, ways);

        return ways;
    }

    // Otherwise there are no ways
    return 0;
}

long long choose(long long a, long long b) {
    if (b > a) return 0;

    //aCb = a!/((a-b)!*b!)
    //    = a*(a-1)...(a-b+1)/
    //      b*(b-1)...1

    //    = a*(a-1)...(a-b+1)/
    //      1*2*......b

    long long result = 1;
    for (int i = 0; i < b; i++) {
        result = (result * (a-i)) % MOD;
        result = (result / (i+1)) % MOD;
    }

    //printf("%lldC%lld = %lld\n", a, b, result);
    return result % MOD;
}


