    } else {
        // Smallest cases
        int n_small = 1 + 2*(k-1);
        int m_small = 1 + 2*(k-1);

        // How many places it can go X inside solutions

        // They must be TWO less
        for (int n_i = n_small; n_i < n-1; n_i++) {
            for (int m_i = m_small; m_i < m-1; m_i++) {
                // Positional permutation (x,y and y,x)
                // int twice = (m_i != n_i) ? 2 : 1;

                //printf("passing: %d %d %lld\n", n_i, m_i, mult);
                oldWaysToPlay(n_i, m_i, k-1, mult*(n-n_i-1)*(m-m_i-1));
            }
        }
