	int j;

	for (j = 0; j  < i; j++) {
		if (s[j].x == x && s[j].y == y) return true;
	}

	return false;
}

void swap (int i, int j) {
	point a =  {s[i].x, s[i].y};

	s[i] = s[j];
	s[j] = a;
}

