int box2mask(char b[5][5]) {
	int mask = 0, i, j, k = 0;
	for (i = 0; i < 5; i++)
		for (j = 0; j < 5-abs(2-i); j++) {
			if (b[i][j])
				mask |= 1 << k;
			k++;
		}

	return mask;
}

int go(int mask) {
	if (r[mask] != -1)
		return r[mask];

	char b[5][5];
	memset(b, 0, sizeof(b));

	int i, j, k = 0;
	for (i = 0; i < 5; i++)
		for (j = 0; j < 5-abs(2-i); j++) {
			if (mask & (1 << k))
				b[i][j] = 1;
			k++;
		}

	char bb[5][5];
	for (i = 0; i < 5; i++)
		for (j = 0; j < 5-abs(2-i); j++) {
			memcpy(bb, b, sizeof(bb));
			for (k = i; k < 5 && j < 5-abs(2-k) && bb[k][j]; k++) {
				bb[k][j] = 0;
				if (!go(box2mask(bb)))
					return r[mask] = 1;
			}

			memcpy(bb, b, sizeof(bb));
			int l;
			for (k = i, l = j; k < 5 && l < 5-abs(2-k) && bb[k][l]; k++, l++) {
				bb[k][l] = 0;
				if (!go(box2mask(bb)))
					return r[mask] = 1;
			}

			memcpy(bb, b, sizeof(bb));
			for (k = j; k < 5-abs(2-i) && bb[i][k]; k++) {
				bb[i][k] = 0;
				if (!go(box2mask(bb)))
					return r[mask] = 1;
			}
		}

	return r[mask] = 0;
}

