#include <stdio.h>
#define MAX 1000

void quick_sort(int *v, int size)
{
	int aux;
	if(size<=1) return;
	else
	{
		int pivot = v[size/2];
		int a =0;
		int b= size-1;
		while(a<b)
		{
			while(v[a]<pivot) a++;
			while(v[b]>pivot) b--;
			if(a<=b)
			{
				aux = v[a];
				v[a] = v[b];
				v[b] = aux;
				a++;
				b--;
			}
			quick_sort(v,b);
			quick_sort(v+a, size-a);
		}
	}
}

