int s1,s2;

int val(char s[], char t[], int i, int j)
{
    int max1 = -1,max = -1;
    for (int k = i; k < s1-(s2-j-1); k++){
        if(s[k]==t[j]){
            if(j < s2-1){
                int temp = val(s,t,k+1,j+1);
                if(temp!=-1){
                    if(temp > k-i) max1 = temp;
                    else max1 = k-i;
                }
                else break;
                if(max1> max) max = max1;
            }
            else{
                if(k - i > s1-k-1) max1 = k - i;
                else max1 = s1 -k -1;
                if (max1 > max) max = max1;
            }
        }
        if(max >= s1-s2) return max;
    }
    return max;
}

