/* practice with Dukkha */
#include <stdio.h>

#define M	150
#define MD	1000000007

int query(int aa[][M + 1], int l0, int l1, int r0, int r1) {
	return l0 > l1 || r0 > r1 ? 0 : ((long long) aa[l1][r1] - aa[l0 - 1][r1] - aa[l1][r0 - 1] + aa[l0 - 1][r0 - 1]) % MD;
}

void add(int aa[][M + 1], int l, int r, int a) {
	aa[l][r] = (aa[l][r] + a) % MD;
}

int main() {
	static int dp00[M + 1][M + 1], dp01[M + 1][M + 1], dp10[M + 1][M + 1], dp11[M + 1][M + 1];
	static int dq00[M + 1][M + 1], dq01[M + 1][M + 1], dq10[M + 1][M + 1], dq11[M + 1][M + 1];
	int n, m, l, r, ans;

	scanf("%d%d", &n, &m);
	ans = 0;
	while (n--) {
		for (l = 1; l <= m; l++)
			for (r = 1; r <= m; r++) {
				dp00[l][r] = (dp00[l][r] + dp00[l][r - 1]) % MD;
				dp01[l][r] = (dp01[l][r] + dp01[l][r - 1]) % MD;
				dp10[l][r] = (dp10[l][r] + dp10[l][r - 1]) % MD;
				dp11[l][r] = (dp11[l][r] + dp11[l][r - 1]) % MD;
			}
		for (l = 1; l <= m; l++)
			for (r = 1; r <= m; r++) {
				dp00[l][r] = (dp00[l][r] + dp00[l - 1][r]) % MD;
				dp01[l][r] = (dp01[l][r] + dp01[l - 1][r]) % MD;
				dp10[l][r] = (dp10[l][r] + dp10[l - 1][r]) % MD;
				dp11[l][r] = (dp11[l][r] + dp11[l - 1][r]) % MD;
			}
		for (l = 1; l <= m; l++)
			for (r = 1; r <= m; r++)
				dq00[l][r] = dq01[l][r] = dq10[l][r] = dq11[l][r] = 0;
		for (l = 1; l <= m; l++)
			for (r = l; r <= m; r++) {
				dq00[l][r] = 1;
				add(dq00, l, r, query(dp00, l, m, 1, r));
				add(dq01, l, r, query(dp01, l, r, r, m));
				add(dq01, l, r, query(dp00, l, r, r + 1, m));
				add(dq10, l, r, query(dp10, 1, l, l, r));
				add(dq10, l, r, query(dp00, 1, l - 1, l, r));
				add(dq11, l, r, query(dp11, 1, l, r, m));
				add(dq11, l, r, query(dp01, 1, l - 1, r, m));
				add(dq11, l, r, query(dp10, 1, l, r + 1, m));
				add(dq11, l, r, query(dp00, 1, l - 1, r + 1, m));
				ans = (ans + (long long) dq00[l][r] + dq01[l][r] + dq10[l][r] + dq11[l][r]) % MD;
			}
		for (l = 0; l <= m; l++)
			for (r = 0; r <= m; r++) {
				dp00[l][r] = dq00[l][r];
				dp01[l][r] = dq01[l][r];
				dp10[l][r] = dq10[l][r];
				dp11[l][r] = dq11[l][r];
			}
	}
	printf("%d\n", ans);
	return 0;
}

