#include<stdio.h>
#include<stdlib.h>
typedef long long unsigned llu;
typedef unsigned u;
typedef struct S
{
	u val,ki,ka,min,max;llu sum;
	struct S *lc,*rc;
}v;
v*alloc(u ki,u ka,u val)
{
	v*x;
	x=(v*)malloc(sizeof(v));
	x->val=val;
	x->min=val;
	x->max=val;
	x->ki=ki;
	x->ka=ka;
	x->sum=(ka-ki+1)*(llu)val;
	x->lc=x->rc=NULL;
	return x;
}
llu que(v *x,u lo,u hi)
{
//	printf("que %u %u\n",lo,hi);
	if(hi<x->ki||lo>x->ka)
	{
//		printf("return 0\n");
		return 0;
	}
	if(lo<=x->ki&&hi>=x->ka)
	{
//		printf("Return %I64u\n",x->sum);
		return x->sum;
	}
	u ll,rr;
	if(x->val)
	{
		ll=lo<x->ki?x->ki:lo;
		rr=hi>x->ka?x->ka:hi;
		if(rr<ll)
		{
//			printf("return -0\n");
			return 0;
		}
//		printf("ll=%u rr=%u x->val=%u\n",ll,rr,x->val);
		return(rr-ll+1)*(llu)x->val;
	}
	llu a=que(x->lc,lo,hi)+que(x->rc,lo,hi);
//	printf("Retu5n %I64u\n",a);
	return a;
}
void set(v *x,u lo,u hi,u val)
{
//	printf("set [%u %u] %u %u %u\n",x->ki,x->ka,lo,hi,val);
	if(hi<x->ki||lo>x->ka||x->min>=val)
	{
//		printf("return %u<%u || %u>%u || %u>=%u\n",hi,x->ki,lo,x->ka,x->min,val);
		return;
	}
	if(lo<=x->ki&&hi>=x->ka&&x->max<=val)
	{
//		printf("chg %u %u -> %u\n",x->ki,x->ka,val);
		x->val=x->min=x->max=val;
		x->sum=val*(llu)(x->ka-x->ki+1);
		return;
	}
	u m;
	if(x->val)
	{
		if(val<=x->val)
		{
//			printf("small return\n");
			return;
		}
//		printf("split!\n");
		m=(x->ki+x->ka)>>1;
		if(!x->lc)x->lc=alloc(x->ki,m,x->val);
		if(!x->rc)x->rc=alloc(m+1,x->ka,x->val);
		x->val=0;
	}
	set(x->lc,lo,hi,val);
	set(x->rc,lo,hi,val);
	if(x->lc->val&&x->lc->val==x->rc->val)
	{
//		printf("unit!\n");
		x->val=x->lc->val;
		x->sum=x->val*(llu)(x->ka-x->ki+1);
	}
	else x->sum=x->lc->sum+x->rc->sum;
	x->min=x->lc->min;
	x->max=x->rc->max;
	return;
}
