ULL n, ans;
void dfs(ULL depth, ULL temp, ULL num, ULL up)
{
    if (num == n && temp < ans) ans = temp;
    if (num >= n || depth == 16) return;
    for (int i = 1; i <= up; ++i)
    {
        if (temp * p[depth] >= ans) return;
        else dfs(depth + 1, temp = temp * p[depth], num * (i + 1), i);
    }
}
