#include<stdio.h>

int main(){
  int D;
  long n, k, M, ans;
  scanf("%ld%ld%ld%d", &n, &k, &M, &D);
  ans = M;
  for(int i = 1; i <= D; i++){
    long cur = n / (k * i);
    long lmax = cur * i;
    if(i < D){
      if(n / cur > k * i){
        lmax += cur;
      } else{
        while(cur && n / cur-- < k * i);
        lmax = lmax > cur * (i + 1) ? lmax : cur * (i + 1);
      }
    }
    ans = ans > lmax ? ans : lmax;
  }
  printf("%ld", ans);
  return 0;
}

