#include <stdlib.h>
#include <stdio.h>


typedef struct _n {
    struct _n *prev, *next;
    int val;
} no;

no *cons(ne, val) no *ne; {
    no *n = calloc(1, sizeof(no));
    n->next = ne; if(ne) ne->prev = n;
    n->val = val;
    return n;
}

no *cycle(n) {
    no *fst = cons(NULL, n);
    no *lst = fst;
    while(--n > 0)
        fst = cons(fst, n);
    lst->next = fst;
    fst->prev = lst;
}

main() {
    int n, a, x, b, y;
    scanf("%d %d %d %d %d", &n, &a, &x, &b, &y);
    no *l = cycle(n);
    no *c1 = l, *c2 = l;

    while(c1->val != a) c1 = c1->next;
    while(c2->val != b) c2 = c2->next;


    while(c1 != c2 && c1->val != x && c2->val != y) {
        c1 = c1->next; c2 = c2->prev;
    }

    if(c1 == c2) puts("YES");
    else puts("NO");
}

