#include <stdio.h>

#define A	300

int solve2(int a1, int a2) {
	static char dp[A + 1][A + 1];
	int i1, i2, i;

	dp[0][0] = 0;
	for (i1 = 0; i1 <= a1; i1++)
		for (i2 = 0; i2 <= a2; i2++) {
			if (dp[i1][i2])
				continue;
			for (i = 1; i1 + i <= a1; i++)
				dp[i1 + i][i2] = 1;
			for (i = 1; i2 + i <= a2; i++)
				dp[i1][i2 + i] = 1;
			for (i = 1; i1 + i <= a1 && i2 + i <= a2; i++)
				dp[i1 + i][i2 + i] = 1;
		}
	return dp[a1][a2];
}

int solve3(int a1, int a2, int a3) {
	static char dp[A + 1][A + 1][A + 1];
	int i1, i2, i3, i;

	dp[0][0][0] = 0;
	for (i1 = 0; i1 <= a1; i1++)
		for (i2 = 0; i2 <= a2; i2++)
			for (i3 = 0; i3 <= a2; i3++) {
				if (dp[i1][i2][i3])
					continue;
				for (i = 1; i1 + i <= a1; i++)
					dp[i1 + i][i2][i3] = 1;
				for (i = 1; i2 + i <= a2; i++)
					dp[i1][i2 + i][i3] = 1;
				for (i = 1; i3 + i <= a3; i++)
					dp[i1][i2][i3 + i] = 1;
				for (i = 1; i1 + i <= a1 && i2 + i <= a2 && i3 + i <= a3; i++)
					dp[i1 + i][i2 + i][i3 + i] = 1;
			}
	return dp[a1][a2][a3];
}

