int mask(int a)
{
	int t=0,ans=0,p=0;
	while(a>0)
	{
		t=a%10;
		a=a/10;
		if(t==7||t==4)
		{
			ans=ans*10+t;
		}
	}
	while(ans>0)
	{
		t=ans%10;
		p=p*10+t;
		ans=ans/10;

	}
	return p;
}


