int gcd(int a, int b)  
{  
    int rem;
    while(b!=0)
    {
        rem =a%b;
        a=b;
        b=rem;
    }
    return a;
}  
// Function to return LCM of two numbers  
int lcm(int a, int b)  
{  
    return (a*b)/gcd(a, b);  
}

