/* https://csacademy.com/submission/2215090/ */
#include <stdio.h>

#define N	50
#define M	(1 << 13) /* 2500 < M / 2 */
#define LN	13
#define MD	1000000007
#define M0	469762049
#define M1	595591169
#define M2	645922817

int MM[] = { M0, M1, M2 };

int V01, V02, V12;

long long power(int a, int b, int md) {
	long long p;

	if (b == 0)
		return 1;
	p = power(a, b / 2, md);
	p = p * p % md;
	if (b % 2)
		p = p * a % md;
	return p;
}

long long ww[3][LN + 1], ww_[3][LN + 1], vv[3];
int kk[N + 1][N + 1][N + 1], ll[N + 1][N + 1][N + 1][3];

void init() {
	int d, h, i, j, k;

	for (d = 0; d < 3; d++) {
		int md = MM[d];

		for (h = 0; h <= LN; h++) {
			ww[d][h] = power(3, (md - 1) >> h, md);
			ww_[d][h] = power(3, md - 1 - ((md - 1) >> h), md);
		}
		vv[d] = power(M, md - 2, md);
	}
	V01 = power(M0, M1 - 2, M1);
	V02 = power(M0, M2 - 2, M2);
	V12 = power(M1, M2 - 2, M2);
	for (i = 0; i <= N; i++)
		for (j = 0; j <= N; j++)
			for (k = 0; k <= N; k++) {
				long long k0, k1, k2;

				k0 = i > 0 ? (long long) ll[i - 1][j][k][0] * i % MD : 0;
				k1 = j > 0 ? (long long) ll[i][j - 1][k][1] * j % MD : 0;
				k2 = k > 0 ? (long long) ll[i][j][k - 1][2] * k % MD : 0;
				if (i == 0 && j == 0 && k == 0) {
					kk[i][j][k] = 1;
					ll[i][j][k][0] = ll[i][j][k][1] = ll[i][j][k][2] = 1;
				} else {
					kk[i][j][k] = (k0 + k1 + k2) % MD;
					ll[i][j][k][0] = (k1 + k2) % MD;
					ll[i][j][k][1] = (k0 + k2) % MD;
					ll[i][j][k][2] = (k0 + k1) % MD;
				}
			}
}

void ntt(int *aa, int d, int inverse) {
	int md = MM[d], h, i, j, b, l, r, u, v, tmp;
	long long w, w_;

	for (i = 1, j = 0; i < M; i++) {
		b = M;
		do
			j ^= b >>= 1;
		while ((j & b) == 0);
		if (i < j)
			tmp = aa[i], aa[i] = aa[j], aa[j] = tmp;
	}
	for (h = 0; (b = 1 << h) < M; h++) {
		w_ = inverse ? ww_[d][h + 1] : ww[d][h + 1];
		for (i = 0; i < M; i += b * 2) {
			w = 1;
			for (j = 0; j < b; j++) {
				l = i + j, r = l + b;
				u = aa[l], v = aa[r] * w % md;
				if ((aa[l] = u + v) >= md)
					aa[l] -= md;
				if ((aa[r] = u - v) < 0)
					aa[r] += md;
				w = w * w_ % md;
			}
		}
	}
}

void fft(int *aa, int *bb, int d) {
	int md = MM[d], i;
	long long v;

	ntt(aa, d, 0), ntt(bb, d, 0);
	for (i = 0; i < M; i++)
		aa[i] = (long long) aa[i] * bb[i] % md;
	ntt(aa, d, 1);
	v = vv[d];
	for (i = 0; i < M; i++)
		aa[i] = aa[i] * v % md;
}

int garner(int r0, int r1, int r2) {
	if (r0 < 0)
		r0 += M0;
	r1 = (long long) (r1 - r0) * V01 % M1;
	if (r1 < 0)
		r1 += M1;
	r2 = ((long long) (r2 - r0) * V02 - r1) % M2 * V12 % M2;
	if (r2 < 0)
		r2 += M2;
	return (((long long) r2 * M1 + r1) % MD * M0 + r0) % MD;
}

void mult(int *aa, int *bb, int *cc) {
	static int cc_[3][M], bb_[M];
	int d, i;

	for (d = 0; d < 3; d++) {
		for (i = 0; i < M; i++) {
			cc_[d][i] = aa[i];
			bb_[i] = bb[i];
		}
		fft(cc_[d], bb_, d);
	}
	for (i = 0; i < M; i++)
		cc[i] = garner(cc_[0][i], cc_[1][i], cc_[2][i]);
}

void knapsack(int *aa, int n, int m, int dp[][M]) {
	int h, i, j, a;

	dp[0][0] = 1;
	for (h = 0; h < n; h++) {
		a = aa[h];
		for (i = n; i >= 1; i--)
			for (j = m; j >= a; j--)
				dp[i][j] = (dp[i][j] + dp[i - 1][j - a]) % MD;
	}
}

int main() {
	static int aa[3][N], cc[M], nn[3], dp[3][N + 1][M];
	int n, m, x, h, i0, i1, i2, j, ans;

	init();
	scanf("%d%d", &n, &m);
	while (n--) {
		scanf("%d%d", &x, &h), h--;
		aa[h][nn[h]++] = x;
	}
	for (h = 0; h < 3; h++)
		knapsack(aa[h], nn[h], m, dp[h]);
	ans = 0;
	for (i0 = 0; i0 <= nn[0]; i0++)
		for (i1 = 0; i1 <= nn[1]; i1++) {
			mult(dp[0][i0], dp[1][i1], cc);
			for (i2 = 0; i2 <= nn[2]; i2++)
				for (j = 0; j <= m; j++)
					ans = (ans + (long long) cc[j] * dp[2][i2][m - j] % MD * kk[i0][i1][i2]) % MD;
		}
	printf("%d\n", ans);
	return 0;
}

#include <stdio.h>

#define max2(a,b) (a<b?b:a)
#define max3(a,b,c) max2(max2(a,b),c)

int N, T;
int L[50];
int G[50];

#define MOD 1000000007ULL
#define add2(a,b) ((a+b)%MOD)
#define add3(a,b,c) add2(add2(a,b),c)
#define mul2(a,b) ((a*b)%MOD)
#define mul3(a,b,c) mul2(mul2(a,b), c)
#define mul4(a,b,c,d) mul2(mul2(a,b), mul2(c,d))
#define fact3(a,b,c) mul3(fact(a),fact(b),fact(c))

typedef unsigned long long u64;

u64 F[51];
u64 fact(u64 n) {
  if (!F[n])
    F[n] = n ? mul2(n, fact(n-1)) : 1;
  return F[n];
}

u64 perm[26][26][26][3];

int n[3];
u64 walk(int t, int c)
{
  if (t > T)
    return 0;
  if (t == T) {
    u64 r = 0;
    for (int g = 0; g < 3; g++)
      r = add2(r, perm[n[0]][n[1]][n[2]][g]);
    r = mul2(r, fact3(n[0],n[1],n[2]));
    // printf("%d [%d,%d,%d]: %d -> %d\n", t, n[0], n[1], n[2], G[c], r);
    return r;
  }

  u64 result = 0;
  for (int i = c + 1; i < N; i++) {
    n[G[i]]++;
    result = add2(result, walk(t + L[i], i));
    n[G[i]]--;
  }

  return result;
}

int main() {
  int i, j, k, n;

  scanf("%d %d", &N, &T);
  for (i = 0; i < N; i++) {
    scanf("%d %d", &L[i], &G[i]);
    G[i]--;
  }

  perm[1][0][0][0] = perm[0][1][0][1] = perm[0][0][1][2] = 1;

  for (n = 2; n <= N; n++)
    for (i = 0; i <= n/2+1; i++)
      for (j = 0; j <= n - i; j++) {
        k = n - i - j;
        if (k > n/2+1) continue;

        if (i) perm[i][j][k][0] = add2(perm[i-1][j][k][1], perm[i-1][j][k][2]);
        if (j) perm[i][j][k][1] = add2(perm[i][j-1][k][2], perm[i][j-1][k][0]);
        if (k) perm[i][j][k][2] = add2(perm[i][j][k-1][0], perm[i][j][k-1][1]);
      }

  printf("%llu\n", walk(0, -1));

  return 0;
}

