#include <stdio.h>
#include <inttypes.h>

/* maximum factors count, 10 must be enough. I take few more ) */
const int64_t cnt = 1000; 

int64_t
decompose(int64_t x, int64_t *p)
{
    /* factors counter */
    int64_t c = 0;
    for (int64_t d = 2, b = x; x*x >= b; ++d)
    {
        if (x % d == 0)
            p[c++] = d;
        while (x % d == 0)
            x /= d;
    }
    if (x != 1) {
        p[c++] = x;
    }
    return c;
}

int
main()
{
    int64_t x;
    int64_t p[cnt];
    scanf("%"SCNd64, &x);

    int64_t c = decompose(x, p);

    int64_t max_f = x;
    int64_t min_f = x - p[c-1] + 1;
    int64_t min = min_f;
    for (int64_t f = min_f; f < max_f; ++f) {
        c = decompose(f, p);
        if ((c != 1 || p[0] != f) && f - p[c-1] + 1 < min)
            min = f - p[c-1] + 1;
    }
    printf("%"PRId64"\n", min);
    return 0;
}

