int main()
{
	int n, m;
	scanf("%d %d", &n, &m);

	int p = power(2, m, MOD);
	int sol = 1;
	int i;
	for (i=1;i<=n;i++)
	{
		int t = p - i;
		if (t<0) t+=MOD;
		sol *= t;
		sol %= MOD;
	}

	printf("%d\n", sol);
	return 0;
}

int power(int base, int exp, int mod)
{
	if (!exp) return 1;
	int t = power(base, exp / 2, mod);
	int tt = (exp & 1)?base:1;
	return (((t * t) % mod) * tt) % mod;
}

