#define sq(A) ((A)*(A))

int x[4], y[4], r[4];

bool intersect(int i, int j){
	int dist=sq(x[i]-x[j])+sq(y[i]-y[j]);
	if(dist>=sq(r[i]+r[j])) return false;
	if(r[i]<r[j] && dist<=sq(r[j]-r[i])) return false;
	if(r[j]<r[i] && dist<=sq(r[i]-r[j])) return false;
	return true;
}

bool in(int i, int j){
	int dist=sq(x[i]-x[j])+sq(y[i]-y[j]);
	if(r[i]<r[j] && dist<=sq(r[j]-r[i])) return false;
	return true;
}

int main(){
