	scanf("%d %d %d %d", x, y, r, r+1);
	x[1]=x[0]; y[1]=y[0];
	scanf("%d %d %d %d", x+2, y+2, r+2, r+3);
	x[3]=x[2]; y[3]=y[2];
	if(!intersect(0, 2) && !intersect(0, 3) && (in(0, 2) ^ in(0, 3))) ++num;
	if(!intersect(1, 2) && !intersect(1, 3) && (in(1, 2) ^ in(1, 3))) ++num;
	if(!intersect(2, 0) && !intersect(2, 1) && (in(2, 0) ^ in(2, 1))) ++num;
	if(!intersect(3, 0) && !intersect(3, 1) && (in(3, 0) ^ in(3, 1))) ++num;
	printf("%d\n", num);
	return 0;
}

