// we will consider numbers with <= 10^6 digits. Hence, maximal sum of digits is 9*10^6 < 10^7.
// we can generate all possible sums for excellent numbers:
//   2^n for n digits of a,b and then we need to sum for n = 1..7, meaning that 2^8 - 2 different possible sums:
//   1+2+..+2^[n-1] = 2^n - 1, hence 2+..+2^[n-1] = 2^n - 2
// now for every possible sum we need to solve:
// ax + by = S
// x + y = N
// and this will add binomial(N,x) numbers
// trivially, writing x = N - y, (b - a)y = S - aN

// now we can do dynamic programming to calculate binomial coefficients up to N
// we just need 2 rows (instead of full table) as we will need only row N

static inline int min(int a, int b) { return a < b ? a : b; }

static int _sd[254] = {};
static void generate_sd(int a, int b) {
    int sd_count = 0;
    for(int i = 1 ; i <= 7 ; ++i) {                // fix number of digits
        for(int j = 0, jn = 1<<i ; j < jn ; ++j) { // enumerate masks
            int n = 0, m = j;
            for(int k = 0, p10 = 1 ; k < i ; ++k, p10 *= 10, m >>= 1)
                n += p10 * (m & 0x1 ? b : a);
            assert(sd_count < 254); _sd[sd_count++] = n;
        }
    }
}

#define MOD 1000000007LL

#define BINN 1000000

static int64_t _binomial_impl[2][1000000+1] = {}, _binomial[1000000+1] = {};

static inline void generate_binomial(int N) {
    _binomial_impl[0][0] = 1; int c = 1, p = 0;
    for(int i = 1 ; i <= N ; ++i) {
        _binomial_impl[c][0] = 1;
        for(int m = 1 ; m <= i ; ++m)
            _binomial_impl[c][m] = (_binomial_impl[p][m-1] + _binomial_impl[p][m]) % MOD;
        int t = c; c = p, p = t;
    }
    for(int i = 0 ; i <= N ; ++i)
        _binomial[i] = _binomial_impl[p][i];
}


int main() {
    int A,B,N; scanf("%d %d %d\n", &A,&B,&N);
    generate_sd(A,B); generate_binomial(N);

    int64_t count = 0;
    for(int si = 0 ; si < 254 ; ++si) {
        const int ss = _sd[si] - A*N;
        if(ss % (B-A) == 0) {
            const int y = ss / (B-A), x = N - y;
            if(x >= 0 && y >= 0)
                count = (count + _binomial[y]) % MOD;
        }
    }

    printf("%d\n", (int)count);
}

