long long bs(long long l, long long r, long long n, long long m)
{
	long long mid=l+((r-l)/2);
	if(l>=r)
	{
		if((mid+1)*2+(mid*(mid+1))/2>=(n-m-1))
			return mid;
		else
			return mid+1;
	}
	if((mid+1)*2 + (mid*(mid+1))/2==(n-m-1))
		return mid;
	if((mid+1)*2 + (mid*(mid+1))/2>(n-m-1))
			return bs(l,mid-1,n,m);
	if((mid+1)*2 + (mid*(mid+1))/2 < (n-m-1))
		return bs(mid+1,r,n,m);
}

