			ans=tmp;
	}
	return ans;
}
int findMin(int n,int k){
	int ans=2e9;
	for(int i=0;i<n;i++){
		int tmp=0;
		for(int j=0;j<k;j++)
			tmp=tmp*10+C[i][j]-'0';
		if( ans>tmp )
			ans=tmp;
	}
	return ans;
}
