int child(int *b, int *c, int i, int n){
    return i - b[i] + c[i] + n - 1; 
}

void fill(double *a, int *b, int *c, int i, double v){
    if(a[i] + v > 1) {
        a[i] = 1;
        fill(a, b, c, child(b, c, i, 1), (v + a[i] - 1)/2);
        fill(a, b, c, child(b, c, i, 2), (v + a[i] - 1)/2);
    }
    else a[i] = a[i] + v;
}

