#include<stdio.h>
void cuprec(float arr[],int num,float amount,int height)
{
	if(arr[num]+amount<=1)
	{
		arr[num]=arr[num]+amount;
	}
	else
	{
		cuprec(arr,num+height+1,(amount-(1-arr[num]))/2,height+1);
		cuprec(arr,num+height,(amount-(1-arr[num]))/2,height+1);
	}
}
int main()
{
	float arr[56];
	int n,t,i,k,ncup,ans=0;
	scanf("%d%d",&n,&t);
	ncup=(n*(n+1))/2;
	for(i=0;i<56;i++)
	{
		arr[i]=0.000;
	}
	for(i=1;i<=t;i++)
	{
		cuprec(arr,1,1.00,1);
	}
	for(i=1;i<=ncup;i++)
	{
		if(arr[i]==1.00)
			ans++;
	}
	printf("%d\n",ans);
	return 0;
}

