void swap(int *lhs, int *rhs) {
    int tmp = *lhs;
    *lhs = *rhs;
    *rhs = tmp;
}

void cpy_team() {
    int i;
    for (i = 0; i < 4; ++i) {
        tmp_team[i].point = team[i].point;
        tmp_team[i].score = team[i].score;
        tmp_team[i].miss = team[i].miss;
        strcpy(tmp_team[i].name, team[i].name);
    }
}

char hash_s[4][25];
int hash_idx = 0;
int hash(const char* str) {
    int i;
    for (i = 0; i < hash_idx; ++i) {
        if (!strcmp(str, hash_s[i])) {
            return i;
        }
    }
    strcpy(hash_s[hash_idx++], str);
    return hash_idx - 1;
}

int comp(const void *lhs, const void *rhs) {
    struct Team *sa = (struct Team *)lhs;
    struct Team *sb = (struct Team *)rhs;
    if (sa->point != sb->point) {
        return sa->point < sb->point;
    }
    if (sa->score - sa->miss != sb->score - sb->miss) {
        return sa->score - sa->miss < sb->score - sb->miss;
    }
    if (sa->score != sb->score) {
        return sa->score < sb->score;
    }
    return strcmp(sa->name, sb->name) > 0;
}

