#define K 100


int sort(int *a, int n) {
	int k;
	for(int i=0; i<n; i++)
		for(int j=i+1; j<n; j++)
			if (a[j]>a[i]) k=a[j], a[j]=a[i], a[i]=k;
}

int n, k;
int a[K];

int solve() {
	int n4 = n, n2 = n*2;

	for(int i=0; n4 && i<k; i++) {
		int d = a[i]/4;
		if (d>n4) d = n4;
		n4 -= d;
		a[i] -= 4*d;
	}
	sort(a, k); while(k && a[k-1]==0) --k;

	for(int i=0; n4 && i<k; i++) if (a[i]==3) n4--, a[i]=0;
	sort(a, k); while(k && a[k-1]==0) --k;

	for(int i=0; n2>2 && i<k; i++) if (a[i]==3) n2-=2, a[i]=0;
	sort(a, k); while(k && a[k-1]==0) --k;

	int cnt[4]={0};
	for(int i=0; i<k; i++) cnt[a[i]]++;
	if (cnt[3]) return 0;
	cnt[2] -= n4;
	cnt[1] -= n4;

	if (cnt[1]<0) cnt[1]=0;
	if (cnt[2]<0) cnt[2]=0;

	return cnt[1]+cnt[2] <= n2;
}

int main() {
	while(scanf("%d %d", &n, &k)==2) {
		for(int i=0; i<k; i++) scanf("%d", &a[i]);
		int ok = solve();
		if (ok) printf("YES\n");
		else printf("NO\n");
		break;
	}
}

