static struct lset_node* lset_impl_get_node(struct lset * _set_, long value) {
    struct lset_node *scan = _set_->root;
    while (scan != ((void *)0)) {
        if (_set_->f_val->cmp(scan->value, value) > 0)
            scan = scan->left;
        else if (_set_->f_val->cmp(scan->value, value) < 0)
            scan = scan->right;
        else
            return scan;
    }
    return ((void *)0);
}
static struct lset_node* lset_impl_get_node_gte(struct lset_node *nd, long value) {
 if (nd == ((void *)0) || nd->value == value) {
  return nd;
 }
 if (nd->value < value) {
  return lset_impl_get_node_gte(nd->right, value);
 }
 struct lset_node *nd_gte = lset_impl_get_node_gte(nd->left, value);
 if (nd_gte) {
  return nd_gte;
 }
 return nd;
}
static struct lset_node* lset_impl_tree_min(struct lset_node* nd) {
 if (nd->left != ((void *)0)) {
  return lset_impl_tree_min(nd->left);
 }
 return nd;
}
static struct lset_node* lset_impl_tree_max(struct lset_node* nd) {
 if (nd->right != ((void *)0)) {
  return lset_impl_tree_max(nd->right);
 }
 return nd;
}
static struct lset_node* lset_impl_tree_predecessor(struct lset_node* nd) {
 if (nd->left != ((void *)0)) {
  return lset_impl_tree_max(nd->left);
 }
 struct lset_node* par = nd->parent;
 while (par != ((void *)0) && nd == par->left) {
  nd = par;
  par = par->parent;
 }
 return par;
}
static struct lset_node* lset_impl_tree_successor(struct lset_node* nd) {
 if (nd->right != ((void *)0)) {
  return lset_impl_tree_min(nd->right);
 }
 struct lset_node* par = nd->parent;
 while (par != ((void *)0) && nd == par->right) {
  nd = par;
  par = par->right;
 }
 return par;
}
