    {
        int w=0;
        b[i]=1000000000;
        //finding maximum restriction for building i for l//
        for(j=0;j<s;j++)
        {
            if((i+1)==l[j])
            {
                w=1;
                if(b[i]<=x[j])
                {
                    continue;
                }
                else
                {
                    b[i]=x[j];
                }
                break;
            }
            else
            {
                continue;
            }
        }
        //finding maximum restriction for building i for r//
        for(j=0;j<s;j++)
        {
            if((i+1)==r[j])
