        if(i==0)
        {
            dp[i]=0;
            if(bit) dp[i]=cost[i];
        }
        else
        {
            if(bit) dp[i]=cost[i]+dp[i-1];
            else dp[i]=min(cost[i],dp[i-1]);
        }
    }
    printf("%lld\n",dp[29]);
