}

#include<stdio.h>
void quicksort(float number[],long long int first,long long int last,float a[],float c[]){
   long long int i, j, pivot;
   float temp;

   if(first<last){
      pivot=first;
      i=first;
      j=last;

      while(i<j){
         while(number[i]<=number[pivot]&&i<last)
            i++;
         while(number[j]>number[pivot])
            j--;
         if(i<j){
            temp=number[i];
            number[i]=number[j];
            number[j]=temp;
			temp=a[i];
            a[i]=a[j];
            a[j]=temp;
			temp=c[i];
            c[i]=c[j];
            c[j]=temp;
         }
      }

      temp=number[pivot];
      number[pivot]=number[j];
      number[j]=temp;
	  temp=a[pivot];
      a[pivot]=a[j];
      a[j]=temp;
	  temp=c[pivot];
      c[pivot]=c[j];
      c[j]=temp;
      quicksort(number,first,j-1,a,c);
      quicksort(number,j+1,last,a,c);

   }
}
