#define SIZE 1000002

static int s[SIZE], p[SIZE], np, min;

static void sieve(void)
{
    int i, j;

    for (i = 2; i < SIZE; i++) {
        if (s[i] == 0) {
            p[np++] = i;

            for (j = 2; i * j < SIZE; j++) {
                s[i * j] = 1;
            }
        }
    }
}

static void solve(int x, int l)
{
    int i, d, lf = -1;

    if (x < min) {
        min = x;
    }

    if (l == 0) {
        return;
    }

    for (i = 0; p[i] <= x / 2; i++) {
        if (x % p[i] == 0) {
            lf = p[i];
        }
    }

    if (lf == -1) {
        return;
    }

    for (d = lf * (x / lf - 1) + 1; d < lf * (x / lf); d++) {
        solve(d, l - 1);
    }
}

