void calculate_result(int index, long long index1){
    if(index >= n){
        if(index1 == 0){
           dp[0] = 0;
           return;
        }
        int i, min = 300,j;
        long long index2 = index1;
        for(i=0;i<n;i++){
            min = (min > (index2 % 300) ) ? (index2 % 300) : min;
            index2 /= 300;
        }
        int win = 0;
        for(i=1;i<=min;i++){
            if(dp[index1 - i*step] == 0){
                win = 1;
                break;
            }
        }
        index2 = index1;
        long long pos = 1;
        if(win == 0){
            for(i=0;i<n;i++){
                int num = index2 % 300;
                for(j=1;j<=num;j++){
                    if(dp[index1 - pos*j] == 0){
                        win = 1;
                        break;
                    }
                }
                if( win == 1 )
                    break;
                index2 /= 300;
                pos *= 300;
            }
        }
        if(win == 1)
            dp[index1] = 1;
        return;
    }
    int i;
    for(i=0;i<=a[index];i++){
        calculate_result(index+1, index1*300 + i);
    }
}

