#include<stdio.h>
#define MOD 1000000007

int dar[252][252], k, n, fact[252];

int add(int a, int b){
  a += b;
  if(a >= MOD)a -= MOD;
  return a;
}

int mul(int a, int b){
  return (a*1ll*b)%MOD;
}
int powmod(int base, long long p){
  int toret = 1;
  while(p){
    if(p&1)toret = mul(toret, base);
    base = mul(base, base);
    p >>= 1;
  }
  return toret;
}

int inv(int x){
  return powmod(x, MOD - 2);
}
int ncr(int n, int r){
  return mul(mul(fact[n], inv(fact[r])), inv(fact[n - r]));
}

int dp(int r, int c){
  //  printf("dp(%d, %d)\n", r, c);
  if(dar[r][c] == -1){
    int toret = 0;
    if(r == 0){
      dar[r][c] = (c == 0);
      return dar[r][c];
    }

    int sat = n - c;
    int i;
    for(i = 0;i <= c;i++)if(i + sat){
      int f1 = powmod(k - 1, c - i);
      f1 = mul(f1, ncr(c, i));
      int f2 = powmod(k, sat);
      if(i == 0){
	f2 = add(f2, MOD - powmod(k - 1, sat));
      }
      toret = add(toret, mul(dp(r - 1, c - i), mul(f1, f2)));
    }
    dar[r][c] = toret;
  }
  return dar[r][c];
}

int main(){
  scanf("%d %d", &n, &k);
  int i,j;
  fact[0] = 1;
  for(i = 1;i < 252;i++)fact[i] = mul(fact[i - 1], i);
  for(i = 0;i <= n;i++)for(j = 0;j <= n;j++){
      dar[i][j] = -1;
    }
  printf("%d\n", dp(n, n));
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
