#define N 2000000
#define MOD 1000000007

int maxp[N + 1];
int lcm[N + 1];
int p[200000];

int max(int x, int y) {
  return x > y ? x : y;
}

int cmp(const void *a, const void *b) {
  return *(int *)b - *(int *)a;
}

int main(void) {
  for (int i = 0; i <= N; i++) {
    maxp[i] = i;
  }
  for (int i = 2; i <= N; i++) {
    if (maxp[i] == i) {
      for (int j = i * 2; j <= N; j += i) {
        maxp[j] = i;
      }
    }
  }

  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &p[i]);
  }
  qsort(p, n, sizeof(int), cmp);
  int one = 0;
  for (int i = 0; i < n; i++) {
    int x = p[i];
    if (lcm[x] == 0) {
      lcm[x] = 1;
      continue;
    }
    bool any = false;
    x--;
    while (x != 1) {
      int p = maxp[x];
      int e = 0;
      while (x % p == 0) {
        x /= p;
        e++;
      }
      if (lcm[p] < e) {
        lcm[p] = e;
        any = true;
      }
    }
    if (!any) {
      one = 1;
    }
  }
  long long ans = 1;
  for (int i = 0; i <= N; i++) {
    for (int j = 0; j < lcm[i]; j++) {
      ans *= i;
      ans %= MOD;
    }
  }
  ans += one;
  ans %= MOD;
  printf("%lld\n", ans);
  return 0;
}

