#include <stdio.h>

char S[200], T[200];
int DP[200][200];
int X[1000], Y[1000];
int M, N;

int main()
{
	//FILE *input, *output;
	//input = fopen("suffix.in", "r");
	int i, j, k, b, d;
	char c;

	for(M=0; ; M++)
	{
		//fscanf(input, "%c", &c);
		scanf("%c", &c);
		if(c == '\n')
			break;
		S[M] = c;
		X[(char) c]++;
	}
	for(N=0; ; N++)
	{
		//fscanf(input, "%c", &c);
		scanf("%c", &c);
		if(c == '\n')
			break;
		T[N] = c;
		Y[(char) c]++;
	}

	if(M < N)
	{
		printf("need tree\n");
		return 0;
	}

	if(M == N)
	{
		for(i=0, b=0; i<1000; i++)
		{
			if(X[i] != Y[i])
				b = 1;
		}

		if(b == 0)
			printf("array\n");
		else
			printf("need tree\n");
		return 1;
	}

	for(i=0; i<N && i<M; i++)
	{
		for(j=0; j<N || j<M; j++)
		{
			if(T[i] != S[j])
				continue;
			if(i == 0)
			{
				DP[i][j] = 1;
				continue;
			}
			for(k=0; k<j; k++)
			{
				if(DP[i-1][k] == 1)
					DP[i][j] = 1;
			}
		}
	}

	if((N < M && DP[N-1][M-1] == 1))
	{
		printf("automaton\n");
		return 1;
	}

	for(i=0, d=0; i<1000; i++)
	{
		if(X[i] < Y[i])
			d = 1;
	}

	if(d == 0)
		printf("both\n");
	else
		printf("need tree\n");
	return 1;
}

