typedef long long int ll;
ll max(ll a,ll b){
    return (a>b?a:b);
}
ll min(ll a,ll b){
    return (a<b?a:b);
}
int main()
{
    ll a,b,c,d,low2,high2,ans=0;
    scanf("%lld %lld %lld %lld",&a,&b,&c,&d);
    for(ll i=d;i>=c;i--)
    {
        for(int j=b;j<=c;j++)
        {
            low2=max(a,i-j+1);
            high2=min(low2,b+1);
            ans+=(b-high2+1);
        }
    }
    printf("%lld",ans);
}

