    if(num == 1) {
        return 1;
    }
    return 1 + 2 * dfs(num / 2);
}
void binsearch(long long le , long long ri , long long num) {
    long long mid = (le + ri) >> 1;
    if(ri < l || le > r || le > ri)
        return ;
    if(mid < l) {
        binsearch(mid + 1 , ri , num / 2);
    }
    else if(mid > r) {
        binsearch(le , mid - 1 , num / 2);
    }
    else {
        ans += num % 2;
        binsearch(le , mid - 1 , num / 2);
        binsearch(mid + 1 , ri , num / 2);
    }
}
