#include <stdio.h>

#define MD	1000000007

int power(int a, int b) {
	int p;

	if (b == 0)
		return 1;
	p = power(a, b / 2);
	p = (long long) p * p % MD;
	if (b % 2 == 1)
		p = (long long) p * a % MD;
	return p;
}

int solve(int x) {
	return power(2, x - 1);
}

int sign(int x) {
	int a, cnt;

	cnt = 0;
	for (a = 2; a * a <= x; a++) {
		if (x % a == 0) {
			x /= a;
			cnt++;
		}
		if (x % a == 0)
			return 0;
	}
	if (x > 1)
		cnt++;
	return cnt % 2 == 0 ? 1 : -1;
}

int main() {
	int x, y, a, sum;

	scanf("%d%d", &x, &y);
	if (y % x != 0) {
		printf("0\n");
		return 0;
	}
	y /= x;
	sum = 0;
	for (a = 1; a * a <= y; a++)
		if (y % a == 0) {
			sum = (sum + (sign(a) * solve(y / a) % MD) + MD) % MD;
			if (y / a != a)
				sum = (sum + (sign(y / a) * solve(a) % MD) + MD) % MD;
		}
	printf("%d\n", sum);
	return 0;
}

