#include <stdio.h>

#define MOD % 998244353

long long C[2501][2501];

void Set_Combination(int a, int b)
{
	if (a == b || b == 0)
	{
		C[a][b] = 1;
		return;
	}
	if (!C[a - 1][b])
		Set_Combination(a - 1, b);
	if (!C[a - 1][b - 1])
		Set_Combination(a - 1, b - 1);
	C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) MOD;
}

long long Permutation(int a, int b)
{
	int k;
	long long r = 1;
	if (b == 0)
		return 1;
	for (k = a; k >= a - b + 1; k = k - 1)
	{
		r = (r * k)MOD;
	}
	return r;
}

void Island(int a, int b, int * ans)
{
	int i, j, small = (a >= b ? b : a);
	long long temp = 0;
	for (i = 0; i <= small;i = i + 1)
	{
		temp = temp + C[b][i] * Permutation(a, i)MOD;
	}
	*ans = (*ans * temp MOD);
	return;
}

