int insert(int x,int fix[]){
	if(x==0){
		fix[0]=0;
		return 1;
	}
	int i,k; i=k=0;
	while(x){
		fix[i++]=x%7;
		x/=7;
	}
	for(k=0;k<i/2;k++){
		int temp = fix[k];
		fix[k] = fix[i-k-1];
		fix[i-k-1]=temp;
	}

	return i;
}
int fill(int x,int fix[],int t){
	int i,k; i=k=0; int lock[250];
	for(i=0;i<x;i++){
		lock[i]=fix[i];
	}
	for(i=0;i<t-x;i++){
		fix[i]=0;
	}
	for(i=t-x;i<x+(t-x);i++){
		fix[i] = lock[k++];
	}
}
