typedef long long i64;
i64 gcd(i64 a, i64 b) {
	return b == 0 ? a : gcd(b, a % b);
}
bool is_prime(i64 n) {
	if(n <= 1) return false;
	else if(n <= 3) return true;
	else if(n % 2 == 0 || n % 3 == 0) return false;
	for(i64 i = 5; i * i <= n; i += 6) if(n % i == 0 || n % (i + 2) == 0) return false;
	return true;
}
i64 f(i64 x, i64 y) {
	i64 ans = 0, d;
	while(y != 0) {
		if(is_prime(x)) {
			ans += x < y ? y / x + y % x : y;
			break;
		}
		while((d = gcd(x, y)) == 1LL && y != 0) ans++, y--;
		if(y == 0) break;
		x /= d, y /= d;
	}
	return ans;
}
int main(void) {
	i64 x, y;
	scanf("%lld%lld", &x, &y);
	printf("%lld\n", f(x, y));
	return 0;
}

