uint64_t getBlkCount(uint32_t l,uint32_t b,uint32_t div)
{
    uint64_t blkCnt = 0;
    for(int i=1;i<=l;i++)
    for(int j=1;j<=b;j++)
    {
        blkCnt+= (((i*i + j*j)%div)==0);
    }
    return blkCnt;
}


uint64_t getCount(uint32_t n,uint32_t m)
{
    int q = n/m, r = n%m;

    uint64_t fullBlkCnt = getBlkCount(m,m,m);
    uint64_t halfBlkCnt = getBlkCount(r,m,m);
    uint64_t remBlkCnt  = getBlkCount(r,r,m);

    uint64_t blkCnt = fullBlkCnt*q*q + halfBlkCnt*2*q + remBlkCnt;

    return (blkCnt);
}

