bool F(int x1, int y1, int x2, int y2, int p){
    if (x1 == 0 && y1 == 0) return true;
    if (x2 == 0 && y2 == 0) return false;
    if (visited[x1][y1][x2][y2][p]) return dp[x1][y1][x2][y2][p];

    bool res = false;
    if (p){
        if (x1 && (x1 - 1) != x2 && F(x1 - 1, y1, x2, y2, p ^ 1)) res = true;
        if (y1 && (y1 - 1) != y2 && F(x1, y1 - 1, x2, y2, p ^ 1)) res = true;
    }
    else{
        res = true;
        if (x2 && (x2 - 1) != x1 && F(x1, y1, x2 - 1, y2, p ^ 1)) res = false;
        if (y2 && (y2 - 1) != y1 && F(x1, y1, x2, y2 - 1, p ^ 1)) res = false;
        if (x2 && y2 && (x2 - 1) != x1 && (y2 - 1) != y1 && F(x1, y1, x2 - 1, y2 - 1, p ^ 1)) res = false;
    }

    visited[x1][y1][x2][y2][p] = true;
    return (dp[x1][y1][x2][y2][p] = res);
}

