#include <stdio.h>

int gcd(int a, int b) {
	return b == 0 ? a : gcd(b, a % b);
}

int binsearch(int a, int x) {
	int low, high, mid;

	low = 1;
	high = a / x;

	while (low <= high) {
		mid = (low + high) / 2;
		if (mid * x < a)
			low = mid + 1;
		else if (mid * x > a)
			high = mid - 1;
		else
			return mid;
	}
	return -1;
}

int main() {
	int a, b, x, y, g;
	long long i, j, k, n, m;

	scanf("%d%d%d%d", &a, &b, &x, &y);
	g = gcd(x, y);
	x /= g, y /= g;
	i = binsearch(a, x);
	j = binsearch(b, y);
	k = a / x < b / y ? a / x : b / y;
	n = i * x, m = i * y;
	if (n * m < j * x * j * y) {
		n = j * x;
		m = j * y;
	}
	if (n * m < k * x * k * y) {
		n = k * x;
		m = k * y;
	}
	if (n < 0)
		n = -n;
	if (m < 0)
		m = -m;
	if (a < x || b < y)
		printf("0 0\n");
	else
		printf("%lld %lld\n", n, m);
	return 0;
}

