#define MAX_N 50000007

int sieve[MAX_N];
int primes[MAX_N];
int main() {
	for( int i=2; i*i<MAX_N; ++i )
		if( sieve[i] == 0 ) {
			primes[++primes[0]] = i;
			sieve[i] = i;
			for( int j = i*i; j<MAX_N; j += i )
				if( sieve[j] == 0 )
					sieve[j] = i;
		}
	long long n;
	scanf("%lld", &n);
	int ans = 0;
	while( n ) {
		++ans;
		if( n < MAX_N ) {
			n -= sieve[n]; continue;
		}
		int isprime = 1;
		for( long long i=1; isprime && i<=primes[0] && primes[i]*primes[i] <= n; ++i )
			if( n%primes[i] == 0 )
				n -= primes[i], isprime = 0;
		if( isprime )
			n = 0;
	}
	printf("%d\n", ans);
}

