    list *ptr1=(list *) malloc(sizeof(list)), *ptr2=(list *) malloc(sizeof(list));
    ptr1->val=v;
    ptr2->val=u;
    ptr1->next=map[u];
    ptr2->next=map[v];
    map[u]=ptr1;
