    if (p==1){
        val=k1h->val;
        k1h=k1h->next;
        if (!k1h)
            k1t=NULL;
    }
    else{
        val=k2h->val;
        k2h=k2h->next;
        if (!k2h)
            k2t=NULL;
    }
    return val;
}
