#include <stdio.h>
#define N 1002
#define MOD 1000000007

typedef long long typec;

int n, m, k;
typec ftable[N];
typec facmod[1000001];

typec extend_gcd(typec a, typec b, typec *x, typec *y)
{
	if(!b) return *x = 1, *y = 0, a;
	typec res = extend_gcd(b, a % b, x, y), tmp = *x;
	*x = *y, *y = tmp - (a / b) * (*y);
	return res;
}

typec inverse(typec a, typec m)
{
	typec x, y;
	y = extend_gcd(a, m, &x, &y);
	while(x < 0) x += m;
	return x;
}

typec pow_mod(typec x, typec k, typec m)
{
	typec res = 1;
	while(x %= m, k) {
		if(k&1) res *= x, res %= m;
		x *= x, k >>= 1;
	}
	return res;
}

int mymin(int x, int y)
{
	return x < y? x : y;
}

typec combines(int i, int j)
{
	if(i < j) return 0;
	return facmod[i] * inverse(facmod[j], MOD) % MOD * inverse(facmod[i - j], MOD) % MOD;
}

void init()
{
	int i, j;
	facmod[0] = 1;
	for(i = 1; i <= 1000000; i++) {
		facmod[i] = facmod[i - 1] * i;
		facmod[i] %= MOD;
	}
	typec sum = 0;
	ftable[1] = 1;
	for(i = 2; i <= n; i++) {
		ftable[i] = pow_mod(i, n, MOD) + MOD;		
		sum = 0;
		for(j = 1; j < i; j++) {
			sum += combines(i, j) * ftable[j] % MOD;
			sum %= MOD;
		}
		ftable[i] -= sum;
		ftable[i] %= MOD;
	}
}


typec calc()
{
	int i, j, m1, m2;
	typec res = 0, tmp, stmp;
	m1 = mymin(n, k);
	for(i = 0; i <= m1; i++) {
		tmp = combines(k, i) * pow_mod(i, (m - 2) * n, MOD) % MOD;
		m2 = mymin(n - i, (k - i) / 2);
		stmp = 0;
		for(j = 0; j <= m2; j++) {
			if(!i && !j) continue;
			stmp += combines(k - i, j) * combines(k - i - j, j) % MOD * ftable[i + j] % MOD * ftable[i + j] % MOD;
			stmp %= MOD;
		}
		res += tmp * stmp % MOD;
		res %= MOD;
	}
	return res;
}
int main()
{
	scanf("%d%d%d", &n, &m, &k);
	init();
	printf("%lld\n", calc());
	return 0;
}

