#include <stdio.h>

#define MD	1000000007

int power(int n, int k) {
	int p;

	if (k == 0)
		return 1;
	p = power(n, k / 2);
	p = (long long) p * p % MD;
	if (k % 2 == 1)
		p = (long long) p * n % MD;
	return p;
}

int main() {
	int n, m, k, sum, x;

	scanf("%d%d", &n, &m);
	sum = 0;
	for (k = 0; k < n; k++) {
		x = power(m + m - 1, k); /* Binomial theorem */
		sum = (sum + x * m % MD * power(m, n - 1 - k)) % MD;
	}
	printf("%d\n", (sum + power(m, n)) % MD);
	return 0;
}

