typedef enum ESCAPE_STAGES {
	EST_DRAGON_WAKE_UP,
	EST_DRAGON_REACH_PRINCESS,
	EST_DRAGON_BACK,
	EST_DRAGON_MAKE_CLEAN,
} EscapeStages;

int main(int argc, char **argv) {

// 	int vp = 1;     // predkosc ksiezniczki w milach na godzine
// 	int vd = 100;	// predkosc smoka w milach na godzine
// 	int t = 10;	    // czas po którym smok spostrzega ze ksiezniczka uciekla
// 	int f = 10;	    // czas spedzony w skarbcu przez smoka na uporzadkowanie
// 	int c = 1000;	// liczba mil od cave'a smoka do zamku

	int vp;
	int vd;
	int t;
	int f;
	int c;

	if( scanf("%d", &vp) == -1 ) return -1;
	if( scanf("%d", &vd) == -1 ) return -1;
	if( scanf("%d", &t) == -1 ) return -1;
	if( scanf("%d", &f) == -1 ) return -1;
	if( scanf("%d", &v) == -1 ) return -1;

	EscapeStages es = EST_DRAGON_WAKE_UP;
	double princessDistance = 0;
	double dragonDistance = 0;
	int numberOfDroppedDiamond = 0;
	int vc = (vd-vp);

	// if dragons speed is smaller or equal then princess', return 0 diamonds
	if(vc<=0) {
		printf("0\n");
		return 0;
	}

	while( princessDistance < c ) {
		switch(es) {
			case EST_DRAGON_WAKE_UP:
				princessDistance += vp*f;
				es = EST_DRAGON_REACH_PRINCESS;
				break;
			case EST_DRAGON_REACH_PRINCESS:
				princessDistance += (double)vp*(double)(princessDistance/(double)vc);
				dragonDistance = princessDistance;
				if(princessDistance<c) numberOfDroppedDiamond++;
				es = EST_DRAGON_BACK;
				break;
			case EST_DRAGON_BACK:
				princessDistance += (double)(dragonDistance/(double)vd)*(double)vp;
				dragonDistance = 0;
				es = EST_DRAGON_MAKE_CLEAN;
				break;
			case EST_DRAGON_MAKE_CLEAN:
				princessDistance += f*vp;
				es = EST_DRAGON_REACH_PRINCESS;
				break;
		};
	}

	printf("%d\n", numberOfDroppedDiamond);

    return 0;
}

