int win(int a1, int b1, int a2, int b2) {
	return a1 > b2 && b1 > a2;
}

int main() {
	int a1, b1, a2, b2, a3, b3, a4, b4;

	scanf("%d%d%d%d%d%d%d%d", &a1, &b1, &a2, &b2, &a3, &b3, &a4, &b4);
	if ((win(a1, b2, a3, b4) && win(a1, b2, a4, b3))
			|| (win(a2, b1, a3, b4) && win(a2, b1, a4, b3))) {
		printf("Team 1\n");
		return 0;
	}
	if ((win(a3, b4, a1, b2) || win(a4, b3, a1, b2))
			|| (win(a3, b4, a2, b1) && win(a4, b3, a2, b1))) {
		printf("Team 2\n");
		return 0;
	}
	printf("Draw\n");
	return 0;
}

