    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);

    if (x1>x2)
        xmove = -1;
    if (x1==x1)
        xmove = 0;
    if (x1<x2)
        xmove = 1;

    if (y1>y2)
        ymove = -1;
    if (y1==y1)
        ymove = 0;
    if (y1<y2)
        ymove = 1;

    while (x1!=x2&&y1!=y2)
    {
        x1 += xmove;
        y1 += ymove;
        summ++;
    }

    if (y1!=y2)
    {
        summ+=(y2-y1)*ymove;
    }
    if (x1!=x2)
    {
        summ+=(x2-x1)*xmove;
    }

    printf("%d", summ);

    return 0;
}

