#include <stdio.h>

int check(int n)
{
	if((n / 2) % 2 == 0) return 1;
	else return 0;
}

int answer(long long num,int n,int h)
{
	int i,j,total = 0,check,temp = 1,temp1 = 0;
	for(i = h;i > 0;i--)
	{
		temp = 1;
		if(i == 1 && (n % 2) == 0)
		{	
			for(j = 0;j < h - i + 1;j++) temp *= 2;
			total += temp;
			continue;
		}
		if((n % 2 == 0 && (n / 2) % 2 == 0) || (n % 2 != 0 && ((n + 1) / 2) % 2 != 0))
		{
			if(i == h)
			{
				total += 2;
				continue;
			}
			for(j = 0;j < h - i + 1;j++) temp *= 2;
			total += temp;
		}
		else 
			total++;
		temp1 = n;
		n /= 2;
		if(temp1 % 2 > 0) 
			n++;
	}
	return total;
}

