#include <stdio.h>

double sub(int w, int b) {
  double win, buf;

  if (w == 0) return 0;

  win = (double)w / (w + b);
  buf = (double)b / (w + b);
  b--;
  if (b <= 0) return win;
  buf = buf * b / (w + b);
  b--;
  if (b == 0)
    win = win + buf * w/(w+b) * sub(w-1, b);
  else
    win = win + buf * w/(w+b) * sub(w-1, b) + buf * b/(w+b) * sub(w, b-1);
  return win;
}

int main() {
  int w, b;
  double win;

  scanf("%d%d", &w, &b);
  win = sub(w, b);
  printf("%.9f", win);

  return 0;
}

