printf("%.9lf\n",pri((double)w,(double)b));
}

double pri(double w,double b){
if(w==0)return 0;
else if(b==0) return 1;
return (w/(w+b))+(b/(w+b))*dra(w,b-1);
}

double dra(double w,double b){
if(b==0)return 0;
else if(w==1&&b==1)return 0;
else if(b==1)return 1/(1+w);
return (b/(b+w))*( (w/(b+w-1))*pri(w-1,b-1) + ((b-1)/(b+w-1))*pri(w,b-2) );
}

