#include<stdio.h>
double tree[1000000]={0};
double prob(int node,double w,double b,double pass)
{
    if(w<=0 || b<=0)
        return;
    tree[2*node]=pass*(b/(w+b))*((b-1)/(w+b-1))*(w/(w+b-2));
    tree[2*node+1]=pass*(b/(w+b))*(w/(w+b-1))*((w-1)/(w+b-2));
    prob(2*node,w,b-3,pass*(b/(w+b))*((b-1)/(w+b-1))*((b-2)/(w+b-2)));
    prob(2*node+1,w-1,b-2,pass*(b/(w+b))*(w/(w+b-1))*((b-1)/(w+b-2)));
}
int main()
{
    double w,b,ans=0;
    int i;
    scanf("%lf%lf",&w,&b);
    tree[1]=w/(b+w);
    prob(1,w,b-1,b/(w+b));
    for(i=1;i<1000000;i++)
        ans+=tree[i];
    printf("%0.9f",ans);
    return 0;
}

