#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N	500

char *color;
int dsu[N];

int find(int x) {
	return dsu[x] < 0 ? x : (dsu[x] = find(dsu[x]));
}

void join(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;
	if (dsu[x] < dsu[y])
		dsu[y] = x;
	else if (dsu[x] > dsu[y])
		dsu[x] = y;
	else {
		dsu[x]--;
		dsu[y] = x;
	}
}

int main() {
	int i, n, m, g1, g2, gcnt1, gcnt2, yes;
	static char cnt[N];
	static int uu[N], vv[N]; 

	scanf("%d%d", &n, &m);
	color = calloc((n + 1), sizeof(*color));
	for (i = 0; i < m; i++) {
		scanf("%d%d", &uu[i], &vv[i]);
		uu[i]--, vv[i]--;
		cnt[uu[i]]++;
		cnt[vv[i]]++;
	}
	for (i = 0; i < n; i++) {
		color[i] = '-';
		dsu[i] = -1;
		if (cnt[i] == n - 1)
			color[i] = 'b';
		cnt[i] = 0;
	}
	for (i = 0; i < m; i++)
		if (color[uu[i]] == '-' && color[vv[i]] == '-') {
			join(uu[i], vv[i]);
			cnt[uu[i]]++;
			cnt[vv[i]]++;
		}
	g1 = g2 = -1;
	gcnt1 = gcnt2 = 0;
	yes = 1;
	for (i = 0; i < n; i++)
		if (color[i] == '-') {
			int group = find(i);

			if (g1 == -1 || g1 == group) {
				g1 = group;
				color[i] = 'a';
				gcnt1++;
			} else if (g2 == -1 || g2 == group) {
				g2 = group;
				color[i] = 'c';
				gcnt2++;
			} else {
				yes = 0;
				break;
			}
		}
	for (i = 0; i < n; i++)
		if (color[i] == '-') {
			int group = find(i);

			if (g1 == group && cnt[i] != gcnt1 - 1) {
				yes = 0;
				break;
			} else if (g2 == group && cnt[i] != gcnt2 - 1) {
				yes = 0;
				break;
			}
		}
	printf("%s\n", yes ? "Yes" : "No");
	if (yes)
		printf("%s\n", color);
	return 0;
}

