// observations:
// mixed holes (any size) will always be 1 complexity no matter what, so they get leftovers at end
// even/odd holes (any size) will always add 0 or 2 (unless on the end)
//     ^ these should definitely be filled from small to large (should i sort then?)
// only question is how to handle the ends with regard to order of filling
// i think you'd want to remove as many 2's as possible then try to fill 1's (might require some backtracking)

typedef struct {
    short parity;
    int size;
} Hole;

int compare(const void *a, const void *b) {
    return ( ((Hole *)a)->size - ((Hole *)b)->size );
}

int main() {
    int n, i;
    int nums[105];
    //int evencnt, mixcnt, oddcnt;  //holes
    //int endholeparity[2] = {0,0};
    int parity[2] = {0,0};         //existing evens,odds
    int complexity = 0;

    int ss,ee;
    Hole start_hole;
    Hole end_hole;
    Hole same_holes[55];
    int same_holes_cnt  = 0;

    int last = -1;

    scanf("%d", &n);
    for (i=0; i < n; i++) {
        scanf("%d", &nums[i]);
        if (nums[i] != 0 && (nums[i] % 2) + last == 1) {
            complexity += 1;
        }
        if (nums[i] != 0) {
            parity[nums[i] % 2]++;
            last = nums[i] % 2;
        }
        else {
            last = -1;
        }
    }
    //printf("base complexity: %d\n", complexity);

    parity[0] = n/2 - parity[0];       //existing/placed -> missing/available evens
    parity[1] = (n+1)/2 - parity[1];

    //printf("Have %2d evens\n     %2d odds\n", parity[0], parity[1]);

    for (i=0; nums[i] == 0 && i < n; i++);
    if (i == n) {     // all zeros
        if (n == 1)
            printf("0\n");
        else
            printf("1\n"); 
        return 0;
    }
    ss = i;
    start_hole.size = i;
    start_hole.parity = nums[i] % 2;
    for (i=n-1; nums[i] == 0 && i >= 0; i--);
    ee = i;
    end_hole.size = (n-1) - i;
    end_hole.parity = nums[i] % 2;

    //printf("start_size: %2d\n", start_hole.size);
    //printf("end_size:   %2d\n", end_hole.size);

    int cur_start = 0;

    for (i = ss; i <= ee; i++) {
        if (nums[i] == 0) {
            Hole hnew;
            cur_start = i;
            while (nums[++i] == 0 && i <= ee);
            hnew.size = i - cur_start; // ee guaranteed nonzero so no off by one
            hnew.parity = nums[cur_start-1] % 2;
            if (nums[i] % 2 != hnew.parity)
                complexity++;
            else 
                same_holes[same_holes_cnt++] = hnew;
        }
    }
    //printf("Found %d holes\n", same_holes_cnt);
    qsort(same_holes, same_holes_cnt, sizeof(Hole), compare);
    for (i=0; i < same_holes_cnt; i++) {
        Hole tt = same_holes[i];
        if (parity[tt.parity] >= tt.size) {
            parity[tt.parity] -= tt.size;
        }
        else {
            complexity += 2;
            //printf("adding complexity\n");
        }
    }
    if (start_hole.size <= end_hole.size && end_hole.size != 0) {
        if (parity[start_hole.parity] < start_hole.size)
            complexity += 1;
        else
            parity[start_hole.parity] -= start_hole.size
        if (parity[end_hole.parity] < end_hole.size)
            complexity += 1;
        else
            parity[end_hole.parity] -= end_hole.size
    }
    else if (end_hole.size < start_hole.size) {
        if (parity[end_hole.parity] < end_hole.size)
            complexity += 1;
        else
            parity[end_hole.parity] -= end_hole.size
        if (parity[start_hole.parity] < start_hole.size)
            complexity += 1;
        else
            parity[start_hole.parity] -= start_hole.size
    }
    printf("%d\n", complexity);
    return 0;
}

