int chi(int a, int b) { return a == b ? 0 : 1; }

int foo(int b, int x, int y, int z)
{
	if (x == n) return 0;
	if (z < 0 || y < 0) return INF;
	if (d[b][x][y][z] != -1) return d[b][x][y][z];
	if (a[x] != -1 && a[x] != b) return INF;
	if (a[x] != -1) return d[b][x][y][z] = min(chi(0, b) + foo(0, x + 1, y, z), chi(1, b) + foo(1, x + 1, y, z));
	return d[b][x][y][z] = min(chi(0, b) + foo(0, x + 1, y - 1, z), chi(1, b) + foo(1, x + 1, y, z - 1));
}

int main()
{
