#include <assert.h>
#include <stdlib.h>
struct heap {
        int cap, last;
        void **cell; 
	int (*cmp)(const void *, const void *);
	#ifdef DIJKSTRA
	void (*set)(void *, const int);
	void (*swap)(void *, void *);
	#endif
};
struct heap *heap_new(int cap, int (*cmp)(const void *, const void*)
	#ifdef DIJKSTRA
	,void (*set)(void *, const int), void (*swap)(void *, void *)
	#endif
)
{
        struct heap *h;
        assert(h = malloc(sizeof(struct heap)));
        h->cap = ++cap;
	h->last = 0;
        assert(h->cell = malloc(sizeof(void*) * cap));
	h->cmp = cmp;
	#ifdef DIJKSTRA
	h->set = set;
	h->swap = swap;
	#endif
        return h;
}
void heap_destroy(struct heap *h)
{
        if (h)
                free(h->cell);
        free(h);
}
void heap_pdown(int x, struct heap *h)
{
        int c, d;
        void *tmp;
        while ((c = 2 * x) <= h->last) {
                d = c + 1;
                if (d <= h->last && h->cmp(h->cell[d], h->cell[c]) < 0)
                        c = d;
                if (h->cmp(h->cell[x], h->cell[c]) < 0)
                        break;
                tmp = h->cell[c];
                h->cell[c] = h->cell[x];
                h->cell[x] = tmp;
		#ifdef DIJKSTRA
		h->swap(h->cell[c], h->cell[x]);
		#endif
                x = c;
        }
}
void heap_pup(int x, struct heap *h)
{
        int p;
        void *tmp;
        while ((p = x / 2) >= 1) {
                if (h->cmp(h->cell[p], h->cell[x]) < 0)
                        break;
                tmp = h->cell[x];
                h->cell[x] = h->cell[p];
                h->cell[p] = tmp;
		#ifdef DIJKSTRA
		h->swap(h->cell[x], h->cell[p]);
		#endif
                x = p;
        }
}
int heap_insert(void *e, struct heap *h)
{
        if (h->last >= h->cap)
                return -1;
        h->cell[++h->last] = e;
	#ifdef DIJKSTRA
	h->set(h->cell[h->last], h->last);
	#endif
        heap_pup(h->last, h);
        return 0;
}
void *heap_del(struct heap *h)
{
        void *ret;
        if (h->last <= 0)
                return NULL;
        ret = h->cell[1];
        h->cell[1] = h->cell[h->last--];
	#ifdef DIJKSTRA
	h->set(h->cell[1], 1);
	#endif
        heap_pdown(1, h);
        return ret;
}
