#define LEN 20000001
struct node {
	long long cost;
	char color;
	long long id;
	int hidx;
};
int compare(const void *x, const void *y)
{
	return ((struct node *)x)->cost - ((struct node *)y)->cost;
}
void sethidx(void *node, const int idx)
{
	((struct node *)node)->hidx = idx;
}
void swaphidx(void *x, void *y)
{
	int tmp;
	tmp = ((struct node *)x)->hidx;
	((struct node *)x)->hidx = ((struct node *)y)->hidx;
	((struct node *)y)->hidx = tmp;
}
long long len;
#define OOS(x) ((x) < 0 || (x) > len)
long long x, y;
struct node nodes[LEN];
void handle(int id, long long cost, struct heap *h)
{
	struct node *next;
	if (OOS(id))
		return;
	next = &nodes[id];
	if (next->color == 2)
		return;
	if (cost >= next->cost)
		return;
	next->cost = cost;
	if (next->color == 0) {
		heap_insert(next, h);
		next->color = 1;
	} else {
		heap_pup(next->hidx, h);
	}
}
long long dijkstra(void)
{
	struct heap *h;
	struct node *node;
	h = heap_new(LEN, compare, sethidx, swaphidx);
	heap_insert(&nodes[0], h);
	nodes[0].color = 1;
	nodes[0].cost = 0;
	while ((node = heap_del(h)) != NULL) {
		node->color = 2;
		if (node->id == len)
			return node->cost;
		handle(node->id + 1, node->cost + x, h);
		handle(node->id - 1, node->cost + x, h);
		handle(node->id * 2, node->cost + y, h);
	}
	return -1;
}
