typedef struct p{
	int x, y;
}ponto;

float isColinear(ponto a, ponto b, ponto c){
	return ( (a.x == b.x && a.y == b.y)||
		(c.x == c.x && a.y == c.y)||
		(b.x == c.x && b.y == c.y)||
		(b.y-a.y)/(b.x-a.x) == (c.y-a.y)/(c.x-a.x));
}

// retorna o angulo no vértice "a"
float isRightAngle(ponto a, ponto b, ponto c){
	if( isColinear(a, b, c)){
		return 0;
	}

	int del_x1 = (b.x - a.x),
		del_x2 = (c.x - a.x),
		del_y1 = (b.y - a.y),
		del_y2 = (c.y - a.y);

	return (del_x1*del_x2 + del_y1*del_y2) == 0;
}

// triangulo, t, é um vetor de pontos
int check(ponto *t){
	if(isRightAngle(t[0], t[1], t[2]) ||
		isRightAngle(t[1], t[0], t[2]) ||
		isRightAngle(t[2], t[1], t[0]))
		return 0;

	int i;
	ponto triangulos[12]; // contém as 4 configurações possívels para o triangulo em cada ponto
	// circula os inteiros vizinhos, começando à esquerda, sentido antihorário
	for (i = 0; i < 3; i++){
		triangulos[4*i] = t[i]; triangulos[4*i].x -=1;
		triangulos[4*i+1] = t[i]; triangulos[4*i+1].y -=1;
		triangulos[4*i+2] = t[i]; triangulos[4*i+2].x +=1;
		triangulos[4*i+3] = t[i]; triangulos[4*i+3].y +=1;
	}

	for(i=0; i<4; i++){
		if(isRightAngle(triangulos[i], t[1], t[2]) ||
			isRightAngle(t[1], triangulos[i], t[2]) ||
			isRightAngle(t[2], t[1], triangulos[i]))
			return 1;
		if(isRightAngle(t[0], triangulos[i+4], t[2]) ||
			isRightAngle(triangulos[i+4], t[0], t[2]) ||
			isRightAngle(t[2], triangulos[i+4], t[0]) )
			return 1;
		if(isRightAngle(t[0], t[1], triangulos[i+8]) ||
			isRightAngle(t[1], t[0], triangulos[i+8]) ||
			isRightAngle(triangulos[i+8], t[1], t[0]) )
			return 1;
	}

	return -1;

}

