typedef struct NODO{
    int Elemento;
    struct NODO *sgt;
}nodo;

nodo* crearNodo(int dato){
    nodo *aux;
	aux=(nodo *)malloc(sizeof (nodo));
	aux->Elemento=dato;
	aux->sgt=NULL;
	return aux;
}

int esVacio(nodo *cabeza){
    if(cabeza==NULL){
        return TRUE;
    }
    return FALSE;
}

void insertarPrimero(int dato,nodo **cabeza){
    nodo *aux;
    if(esVacio(*cabeza)){
        aux=crearNodo(dato);
    }else{
        aux=crearNodo(dato);
        aux->sgt=*cabeza;
    }
	*cabeza=aux;
}

int desApilar(nodo **cabeza){
    int dato;
    nodo *aux=*cabeza;
    dato = aux->Elemento;
    *cabeza=aux->sgt;
	free(aux);
   return dato;
}

int desEncolar(nodo **cabeza){
    int dato;
    nodo *aux=*cabeza;
    if(aux->sgt){
		while(aux->sgt->sgt!=NULL){
            aux=aux->sgt;
        }
        dato=aux->sgt->Elemento;
        free(aux->sgt);
        aux->sgt=NULL;
    }else{
        dato=aux->Elemento;
		free(aux);
        *cabeza=NULL;
    }
    return dato;
}

