    nodo *aux;
	aux=cabeza;
    if(!esVacio(aux)){
        while (aux!=NULL){
            printf("%d\n",aux->Elemento);
            aux=aux->sgt;
        }
    }else{
        printf("La lista esta vacia\n");
	}
    printf("\n");
}

