	/* (a1k + b1 = a2l + b2) = (a1k - a2l = b2 - b1) */
	g = gcdxy(a1, -a2);
	b = (long long) b2 - b1;
	if (b % g != 0)
		printf("0\n");
	else {
		k_ = xy[0] * b / g, l_ = xy[1] * b / g;
