			g = -g;
		cnt2 = a2 / g;
		cnt1 = a1 / g;
		cnt = (long long) a1 / g * a2;
		k_ = (k_ % cnt2 + cnt2) % cnt2;
		l_ = (l_ % cnt1 + cnt1) % cnt1;
		x = a1 * k_ + b1 > a2 * l_ + b2 ? a1 * k_ + b1 : a2 * l_ + b2;
		n = 0;
