int low[7][7], high[7][7];
int cost[7][7];
int n;
int flow[7][7];
int inFlow[7];
int outFlow[7];
int minFlow = 100, maxCost = -1;

int rec(int v, int to) {
    if(v == n - 1) {
        int isValid = 1;
        int i, j;
        int total = inFlow[n - 1];
        int ccost = 0;
        for(i = 0; i < n; i++) {
            for(j = i + 1; j < n; j++) {
                if(flow[i][j] < low[i][j] || flow[i][j] > high[i][j])
                    isValid = 0;
                if(flow[i][j] > 0) 
                    ccost += flow[i][j] * flow[i][j] + cost[i][j];
            }
            if(inFlow[i] != outFlow[i] && (i > 0 && i < n - 1)) {
                isValid = 0;
            }
        }
        if(isValid) {
            if(minFlow == total) {
                if(ccost > maxCost)
                    maxCost = ccost;
            } else if(minFlow > total) {
                minFlow = total;
                maxCost = ccost;
            }
        }
    } else if(to == n)
        rec(v + 1, v + 2);
    else {
        int i;
        for(i = 0; i <= high[v][to]; i++) {
            inFlow[to] += i;
            outFlow[v] += i;
            flow[v][to] = i;
            rec(v, to + 1);
            inFlow[to] -= i;
            outFlow[v] -= i;
        }
    }
}

int main() {
    scanf("%d", &n);
    int i, from, to, j;
    for(i = 0; i < n * (n - 1) / 2; i++) {
        scanf("%d %d", &from, &to);
        from--;
        to--;
        scanf("%d %d %d", &low[from][to], &high[from][to], &cost[from][to]);
    }
    rec(0, 1);
    if(minFlow == 100)
        puts("-1 -1");
    else
        printf("%d %d\n", minFlow, maxCost);
    return 0;
}

