#include <stdio.h>
int mod=(int)1e9+7;
int powmod(int a,int n)
{
    int ans=1;
    while(n)
    {
        if(n&1) ans=((long long)ans*a)%mod;
        a=((long long)a*a)%mod;
        n>>=1;
    }
    return ans;
}
int main()
{
    long long x,k;
    scanf("%lld%lld",&x,&k);
    x%=mod;
    k%=(mod-1);
    int temp=powmod(2,k);
    int ans=((long long)2*temp)%mod;
    ans=((long long)ans*x)%mod;
    if(temp) temp=mod-temp;
    ans=((long long)ans+temp+1)%mod;
    printf("%d\n",ans);
    return 0;
}

