int ktree(int n,int k,int d) {
  if(dp[n][d]!=-1) return dp[n][d];
  int i=1,b=0;
  if(k>=n) b+=1;
  if(n==d) dp[n][d]= 1;
  else if(n<d) dp[n][d]= 0;
else{
  while(i<d  && i<=k)
  {
	  b+=ktree(n-i,k,d);
	  i++;
  }
  while(i>=d && i<=k)
  {
	  b+=ktree(n-i,k,1);
	  i++;
  }
  dp[n][d]= b;
}
return dp[n][d];
}
