int countPaths(int n, int k, int d) {
	long long state[n+1][2], sum;
	int i, j;
	state[0][0] = 1;
	state[1][0] = 1;

	for(i=0;i<d;i++) {
		state[i][1] = 0;
	}
	state[d][1] = 1;

	for(j=2;j<=n;j++) {
		sum = 0;
		for(i=1; j-i>=0 && i<=k ;i++) {
			sum += (state[j-i][0])%1000000007ll;
		}
		state[j][0] = sum%1000000007ll;
	}

	for(j=d+1;j<=n;j++) {
		sum = 0;
		for(i=1; j-i>=0 && i<=k ; i++) {
			sum+= ((i>=d)?state[j-i][0]:state[j-i][1])%1000000007ll;
		}
		state[j][1] = sum%1000000007ll;
	}

	return state[n][1];
}

