	long long int x[102], y[102];
	x[0] = x0;
	y[0] = y0;
	long long int i, j;
	for (i = 0; x[i] <= t && y[i] <= t; i++)
	{
		x[i + 1] = ax * x[i] + bx;
		y[i + 1] = ay * y[i] + by;
	}
	long long int c = i + 1;
	long long int ans = 0;
	for (i = 0; i < c; i++)
		for (j = 0; j < c; j++)
