int mod=1000000007;
int dp[2001][2001];
int f(int n,int k);
int uf(int n,int k)
{
	return f(n,k)-f(n-1,k);
}
int f(int n,int k)
{

	if(dp[n][k]!=0)
	{
		return dp[n][k];
	}

	if(n==1)
		dp[n][k]=1;
	else if(k==1)
		dp[n][k]=n;
	else{
	int i,p=0,j=0;
	int div;
	for(i=n/2;i>=0;i--)
	{
		if(n%i==0)
		{
			div=i;
			break;
		}
	}
	int non[div];
	for(i=2;i<div;i++)
	{
		if(n%i!=0)
		{
			non[p]=i;
			p++;
		}
	}
	int c=0;
//	for(j=0;j<p;j++)
//	{
//		c+=(c%mod + uf(non[j],k-i)%m)%m
//	}
	int b=0;
	for(i=1;i<k;i++)
	{
		for(j=0;j<p;j++)
		{
			c+=(c%mod + uf(non[j],k-i)%mod)%mod;
		}


		b=(b%mod+(f(div,k-i))%mod-c)%mod;
	}

	dp[n][k]=((f(n-1,k))%mod+b%mod+1)%mod;
	}
	return dp[n][k];

}

