#include <inttypes.h>

const char* f0  = "What are you doing at the end of the world? Are you busy? Will you save us?";
const char* fi1 = "What are you doing while sending \"";
const char* fi2 = "\"? Are you busy? Will you send \"";
const char* fi3 = "\"?";

static const int f0len = 75, fi1len = 34, fi2len = 32, fi3len = 2;

static char dfs(int64_t N, int64_t* K) {
    const int64_t k1 = *K;
    if(N == 0) {                    // leaf of the tree
        if(k1 >= f0len) {
            *K -= f0len; return '.';
        } else {
            *K = 0; return f0[k1];
        }
    }
    if(k1 < fi1len) {               // inside fi1
        *K = 0; return fi1[k1];
    }
    *K -= fi1len;

    const char c1 = dfs(N-1, K);    // dfs into the first recursive part
    if(c1 != '.') return c1;

    const int64_t k2 = *K;
    if(k2 < fi2len) {               // inside fi2
        *K = 0; return fi2[k2];
    }
    *K -= fi2len;

    const char c2 = dfs(N-1, K);
    if(c2 != '.') return c2;        // dfs into the second recurse part

    const int64_t k3 = *K;
    if(k3 >= fi3len) {
        *K -= fi3len; return '.';
    } else {                        // inside fi3
        *K = 0; return fi3[k3];
    }
}

int main() {
    int Q; scanf("%d\n", &Q); while(Q--) {
        int64_t N,K; scanf(" %"PRId64 " %"PRId64 "\n", &N, &K);
        --K; printf("%c", dfs(N,&K));
    }
    printf("\n");
    return 0;
}

