#include <stdio.h>
int main()
{
    int a ,old_a , b , old_b , w , x , c , old_c , count = 0 ;
    scanf("%d %d %d %d %d", &a, &b, &w, &x, &c);
    old_b = b ; old_a = a ; old_c = c ;
    while(c > a)
    {
        count++;
        c--;
        if(b >= x)
            b -= x;
        else
        {
            a--;
            b = w - (x - b);
        }
        if(b == old_b)
            break;
    }
    if(c <= a)
        printf("%d\n", count);
    else
    {
        int ax , cx , flag ;
        ax = old_a - a ;
        cx = old_c - c ;
        flag = (old_c-old_a)/(cx-ax) ;
        flag--;
        count = count*flag;
        a = old_a - flag*ax;
        c = old_c - flag*cx;
        while(c > a)
        {
            count++;
            c--;
            if(old_b >= x)
            old_b -= x;
            else
            {
                a--;
                old_b = w - (x - old_b);
            }
        }
        printf("%d\n", count);
    }
    return 0;
}

