int ans, MOD = 100000000;
int k1, k2;

int min(int a, int b) { return a < b ? a : b; }

void rec(int remain1, int remain2, int turn) {
    if(remain1 + remain2 == 0) {
        ans++;
        if(ans == MOD)
            ans = 0;
    } else {
        int i, val;
        if(turn == 0) {
            val = (remain1 + k1 - 1) / k1;
            if(val > 1 && val - 1 > remain2)
                return;
            for(i = 1; i <= min(k1, remain1); i++) {
                rec(remain1 - i, remain2, 1);
            }
        } else {
            val = (remain2 + k2 - 1) / k2;
            if(val > 1 && val - 1 > remain1)
                return;
            for(i = 1; i <= min(k2, remain2); i++) {
                rec(remain1, remain2 - i, 0);
            }
        }
    }
}

