int isluck(long long n)
{
	while (n)
	{
		if (n % 10 == 7 || n % 10 == 4)
			n /= 10;
		else
			return 0;
	}
	return 1;
}



long long nearby(long long n)
{
	while (isluck(n) != 1)
	{
		n++;
	}
	return n;
}

int main()
{
	long long  l, r;

	while (~scanf("%lld %lld", &l, &r))
	{
		long long sum = 0;

		while (l <= r)
		{
			int tmp = nearby(l);
			if (tmp > r)
			{
				sum += (r - l + 1) * tmp;
				break;
			}
			sum += (tmp - l + 1) * tmp;
			l = tmp + 1;
		}
		printf("%lld\n", sum);
	}

	return 0;
}

