static int64_t _factorial[19] = {};

// generates permutation of [0, .., n-1]
static void generate_kth_permutation(int n, int64_t k, int v[static n]) {
    bool taken[n]; for(int i = 0 ; i < n ; ++i) taken[i] = false;
    for(int i = 0 ; i < n ; ++i) {
        const int64_t f = _factorial[n-i-1];
        int64_t q,r; if(k < f) {
            r = k, q = 0;
        } else {
            r = k % f; if(r == 0) r = f; // 0 < r <= m!
            q = (k - r) / f;
        }
        int qi = 0; for(int j = 0, ti = 0, tn = q+1 ; ti < tn ; ++j)
            if(!taken[j]) qi = j, ++ti;

        v[i] = qi; taken[qi] = true; k = r;
    }
}

// sort digits of in increasing order, and generate permutations
// use binary search to find needed permutation

static int compare_digit(const void* a, const void* b) { return *(const int*)a - *(const int*)b; }

static inline int64_t number_from_digits_perm(int n, int perm[static n], int d[static n]) { int64_t ret = 0;
    if(d[perm[0]] == 0) return 0;
    for(int i = 0 ; i < n ; ++i)
        ret = 10*ret + d[perm[i]];
    return ret;
}

static inline bool perm_gt(int n, int64_t pn, int d[static n], int64_t V) {
    int perm[n]; generate_kth_permutation(n, pn, perm);
    const int64_t a = number_from_digits_perm(n, perm, d);
    return a > V;
}

static inline bool perm_lt(int n, int64_t pn, int d[static n], int64_t V) {
    int perm[n]; generate_kth_permutation(n, pn, perm);
    const int64_t a = number_from_digits_perm(n, perm, d);
    return a <= V;
}

static inline int64_t solve(int64_t a, int64_t b) {
    int adcount = 0; int ad[19]; while(a) {
        ad[adcount++] = a % 10; a /= 10;
    }
    qsort(ad, adcount, sizeof(int), compare_digit);

    int64_t low = 0, high = _factorial[adcount]+1;      /* start with whole array                   */
    while(high - low > 1) {                             /* more than one candidate                  */
        const int mid = low + (high - low) / 2;         /* pick middle                              */
        if(perm_gt(adcount, mid, ad, b)) high = mid;    /* higher than b: no need to consider it    */
        else                             low = mid;
    }

    int aperm[adcount]; generate_kth_permutation(adcount, low, aperm);
    return number_from_digits_perm(adcount, aperm, ad);
}

int main() {
    _factorial[0] = 1; for(int i = 1 ; i < 19 ; ++i) _factorial[i] = i*_factorial[i-1];
    int64_t a, b; scanf("%"PRId64 " %"PRId64 "\n", &a, &b);
    printf("%" PRId64 "\n", solve(a,b));
}

