__int64 countArr(int size, int max)
{
    __int64 result = 0;
    __int64 temp;
    int m, i;

    for(m=size-1;m<=max;m++) //middle's min is size-1 
    {
        temp = 0;
        for(i=0;i<size-2;i++)
        { 
            temp += factorial(m-2)/(factorial(m-i-2) * factorial(i)); 
        }
        result += temp * (m-1);
    }
    return result % MOD;
}

