/*

Vasya has found a strange device. On the front panel of
a device there are: a red button, a blue button and a
display showing some positive integer. After clicking
the red button, device multiplies the displayed number
by two. After clicking the blue button, device subtracts
one from the number on the display. If at some point
the number stops being positive, the device breaks down.
The display can show arbitrarily large numbers.
Initially, the display shows number n.

Bob wants to get number m on the display. What minimum
number of clicks he has to make in order to achieve this result?

Input
The first and the only line of the input contains
two distinct integers n and m (1 <= n, m <= 10000),
separated by a space.

Output
Print a single number � the minimum number of times one
needs to push the button required to get the number m out
of number n.

*/

typedef struct Pair {
    int data;
    int distance;
} Pair;

struct QueueElem{
    Pair pair;
    struct QueueElem* next;
};

Pair makePair(int f, int s){
    Pair p = {f, s};
    return p;
}

typedef struct QueueElem Elem;

struct Queue{
    Elem *front; // sa fronta uklanjam
    Elem *rear; // na rear dodajem
};

typedef struct Queue Queue;

void init(Queue *q){
    q->front = NULL;
    q->rear = NULL;
}

void destroy(Queue *q){ // treba svaki Elem brisat jer je pravljen sa malloc
    free(q->front);
    free(q->rear);
}

int isEmpty(Queue *q){
    return (q->front == NULL && q->rear == NULL);
}

//void print(Queue *q){
//    for(Elem *curr = q->front; curr != NULL; curr = curr->next){
//        printf("%d ", curr->data);
//    }
//    printf("\n");
//}

void enqueue(Queue *q, Pair p){
    Elem *newElem = malloc(sizeof(Elem));
    newElem->pair = p;
    newElem->next = NULL;

    if(q->rear == NULL){
        q->front = newElem;
        q->rear = newElem;
    }
    else{
        q->rear->next = newElem;
        q->rear = newElem;
    }
}

Pair dequeue(Queue *q){
    if(isEmpty(q)){
        return makePair(-10000, -10000);
    }
    Pair temp = q->front->pair;

    Elem *tmp = q->front;
    q->front = q->front->next;
    free(tmp);
    //tmp = NULL;

    if(q->front == NULL){
        q->rear = NULL;
    }
    return temp;
}

Pair peek(Queue *q){
    if(q->front != NULL) return q->front->pair;
    else return makePair(-10000, -10000);
}

// a greedy BFS sounds fine, maybe for small inputs, we'll see
// what code forces says

void solve(){
    int n, m;
    scanf("%d%d", &n, &m);

    Queue q1;
    Queue *q = &q1;
    init(q);
    enqueue(q, makePair(n, 0));

    while(!isEmpty(q)){
        Pair curr = dequeue(q);
        if(curr.data == m){
            printf("%d", curr.distance);
            return;
        }
        enqueue(q, makePair(curr.data*2, curr.distance+1));
        if(curr.data-1 >= 0){
            enqueue(q, makePair(curr.data-1, curr.distance+1));
        }
    }
}

int main()
{
    solve();
    return 0;
}

