int invite(struct point *nom[],int n,struct point *pts[],int m,struct point *invite[]){
	int i,j,idx=0;
	for(i=0;i<n;i++){
		for(j=0;j<m;j++){
			if(nom[i]->x==pts[j]->x || nom[i]->y==pts[j]->y){
				if(pts[j]->visit==0){
					invite[idx++]=pts[j];
					pts[j]->visit=1;
