	return 0;
}
int find(struct node *p,struct node *node[]){
	int i,j,k;
	int count=0;
	for(i=0;i<p->n;i++){
		if(p->nei[i]==-1)
			continue;
		for(j=0;j<node[p->nei[i]]->n;j++){
			if(node[p->nei[i]]->nei[j]==-1)
				continue;
			for(k=0;k<p->n;k++){
				if(p->nei[k]==-1)
					continue;
				if(node[p->nei[i]]->nei[j]==p->nei[k])
					count++;
			}
		}
	}

	return count;
}
void rem(struct node *p,struct node *nodes[],int n){
	int i,j;
	for(i=0;i<n;i++){
		if(nodes[i]==NULL)
			continue;
		for(j=0;j<nodes[i]->n;j++)
			if(nodes[i]->nei[j]==p->id)
				nodes[i]->nei[j]=-1;
	}
}
