int main() {
	int n,k;
	scanf("%d%d",&n,&k);
	int v=(k-1)*n/k;
	int result=v;
	//printf("v=%d\n",v);
	while(1){
		int sum=0;
		int kk=1;
		while(1){
			if(v<kk)break;
			sum+=(v/kk);
			kk*=k;
		}
		//printf("sum=%d\n",sum);
		if(sum>=n){
			result=v;
			break;
		}
		v++;
	}
	printf("%d\n",result);
	return 0;
}

