int A, min = 0, max = 0;

void run(int a)
{
    int i, remain;

    remain = a%7;
    //result = a/7;
    //printf("remain %d\n", remain);
    //printf("result %d\n", result);

    if (remain==0)
    {
        min = 2*(a/7);
        max = min; return;
    }
    if (remain < 2)
    {
        min = 2*(a/7);
        max = min + 1; return;
    }
    if (remain >= 6)
    {
        min = 1 + 2*((a-1)/7);
        max = 2 + 2*((a-1)/7); return;
    }
    if ((remain >= 2) && (remain < 6))
    {
        min = 2*(a/7);
        max = min + 2; return;
    }
//    min = 2*(a/7)+(remain-5);
//    max = 2*((a-2)/7) + 2;
//    return;
}

int main()
{
    scanf("%d", &A);
    run(A);
    printf("%d %d", min, max);
    return 1;
}

