int segCalc(int number){
	if(number==4){
		return 4;
	}else if (number==1){
		return 2;
	}else if (number==2||number==5||number==3){
		return 5;
	}else if (number==6||number==0){
		return 6;
	}else if (number==7){
		return 3;
	}else if (number==8){
		return 8;
	}else if (number==9){
		return 7;
	}


}
long findSeg(long i){
	long seg;
	int temp;
	if(i/10==0){
		seg= segCalc(i);
		return seg;
	}
	else{
		temp=i%10;
		seg=segCalc(temp);

		return seg+findSeg(i/10);
	}

}
