#define ll long long

int count[20000];

void deal(int n, int a, int b, int c)
{
    int i, j;
    ll ans = 0;
    memset(count, 0, sizeof(count));
    for (i = 0; i <= b; i++)
    {
        for (j = 0; j <= c; j++)
        {
            count[i + 2 * j]++;
        }
    }
    for (i = 0; i <= a; i += 2)
    {
        ans += count[n - i / 2];
    }
    printf("%lld\n", ans);
}

