#include<stdio.h>

#define MOD 998244353
int fact[1000006], wpar[1000006<<1], n, level;

int mul(int a, int b){
  return (a*1ll*b)%MOD;
}

int powmod(int p, int b){
  int t = 1;
  while(p){
    if(p&1)t = mul(t, b);
    b = mul(b, b);
    p>>=1;
  }
  return t;
}

int ncr(int n, int r){
  return mul(mul(fact[n], powmod(fact[r], MOD - 2)), powmod(fact[n - r], MOD - 2));
}

void dfs(int x, int bits){
  if(bits > level) return;
  int l, r;
  l = x<<1;
  r = l|1;
  if(x&1){
    // x is a right child
    wpar[l] = 1;
    wpar[r] = 1^wpar[x]^wpar[l];
  } else {
    // x is a left child
    wpar[r] = 0;
    wpar[l] = 1^wpar[x]^wpar[r];
  }
  dfs(l, bits + 1);
  dfs(r, bits + 1);
}

int getpossib(int lparity){
  int i, rem, choice;
  wpar[2] = lparity;
  wpar[3] = wpar[1]^wpar[2];
  dfs(2, 2);dfs(3, 2);

  rem = n - (1<<level) + 1;
  choice = 0;
  for(i = (1<<(level - 1));i < (1<<level);i++){
    if(i&1){
      if(wpar[i]) return 0;
      rem--;
      choice++;
    } else {
      choice++;
      if(1^wpar[i]) rem--;
      else choice++;
    }
  }

  if(rem < 0 || rem&1 || (rem>>1) > choice) return 0;
  return ncr(choice, rem>>1);
}

int main(){
  int i;
  scanf("%d", &n);

  fact[0]  = 0;
  for(i = 1;i < 1000006;i++)fact[i] = mul(fact[i - 1], i);

  if(n == 1 || n == 2 || n == 4 || n == 5){printf("1\n");return 0;}
  if(n == 3 || n == 6 || n == 7){printf("0\n");return 0;}

  for(level = 0; (1<<level) - 1 < n;level++);
  level -= 2;
  wpar[1] = n&1;

  int ans;
  ans = (getpossib(0) + getpossib(1))%MOD;

  printf("%d\n", ans);

  return 0;
}

