#include <stdio.h>

#define N	100000
#define MD	1000000007

int ff[N], gg[N];

int d_, x_, y_;

void gcd_(int a, int b) {
	if (b == 0) {
		d_ = a;
		x_ = 1, y_ = 0;
	} else {
		int tmp;

		gcd_(b, a % b);
		tmp = x_ - a / b * y_, x_ = y_, y_ = tmp;
	}
}

int inv(int a, int b) {
	gcd_(a, b);
	return x_;
}

void init(int n) {
	int i, f;

	for (i = 0, f = 1; i < n; i++) {
		gg[i] = inv(ff[i] = f, MD);
		f = (long long) f * (i + 1) % MD;
	}
}

int choose(int n, int k) {
	return n < k ? 0 : (long long) ff[n] * gg[k] % MD * gg[n - k] % MD;
}

int main() {
	static int aa[N + 2], bb[N + 2], cc[N + 2];
	int f, w, h, n, i, j, p, q, ans;

	scanf("%d%d%d", &f, &w, &h);
	if (f == 0) {
		printf("%d\n", w > h);
		return 0;
	}
	if (w == 0) {
		printf("1\n");
		return 0;
	}
	n = f > w ? f : w;
	init(n);
	for (i = 1; i <= f; i++)
		aa[i] = choose(f - 1, i - 1);
	for (j = 1; j <= w; j++)
		bb[j] = choose(w - 1, j - 1);
	for (j = 1; h * j < w; j++)
		cc[j] = choose(w - h * j - 1, j - 1);
	p = q = 0;
	for (i = 1; i <= n; i++) {
		p = (p + aa[i] * (cc[i] * 2LL + cc[i - 1] + cc[i + 1])) % MD;
		q = (q + aa[i] * (bb[i] * 2LL + bb[i - 1] + bb[i + 1])) % MD;
	}
	ans = (long long) p * inv(q, MD) % MD;
	if (ans < 0)
		ans += MD;
	printf("%d\n", ans);
	return 0;
}

