#include <stdio.h>

#define INF (1LL << 60)

struct point
{
    int x;
    int y;
};

struct point p[4][2];
int q[4];
double g[4];

int check(struct point p1, struct point p2)
{
    if (p1.x == p2.x && p1.y == p2.y)
    {
        return 1;
    }
    return 0;
}

void solve()
{
    int i, j, k, t, f;
    for (i = 0; i < 4; i ++)
    {
        if (check(p[i][0], p[i][1]))
        {
            printf("NO\n");
            return;
        }
        k = t = 0;
        for (j = 0; j < 4; j ++)
        {
            f = 0;
            if (j == i)
            {
                continue;
            }
            if (check(p[i][0], p[j][0]))
            {
                k ++;
                f = 1;
            }
            if (check(p[i][0], p[j][1]))
            {
                k ++;
                f = 1;
            }
            if (k > 1)
            {
                printf("NO\n");
                return;
            }
            if (check(p[i][1], p[j][0]))
            {
                t ++;
                f = 1;
            }
            if (check(p[i][1], p[j][1]))
            {
                t ++;
                f = 1;
            }
            if (t > 1)
            {
                printf("NO\n");
                return;
            }
            if (f == 0)
            {
                q[i] = j;
            }
        }
        if (k != 1 || t != 1)
        {
            printf("NO\n");
            return;
        }
        if (p[i][0].x == p[i][1].x)
        {
            g[i] = INF;
        }
        else
        {
            g[i] = (double)(p[i][1].y - p[i][0].y) / (p[i][1].x - p[i][0].x);
        }
    }
    for (i = 0; i < 4; i ++)
    {
        if (g[i] != g[q[i]])
        {
            printf("NO\n");
            return;
        }
    }
    printf("YES\n");
}

int main()
{
    int i;
    for (i = 0; i < 4; i ++)
    {
        scanf("%d%d%d%d", &p[i][0].x, &p[i][0].y, &p[i][1].x, &p[i][1].y);
    }
    solve();
    return 0;
}

