#define MAX 100
#define MAX_VALUE 1000000000000000000L

typedef unsigned long long UINT64;

int maxIndex = 0;
UINT64 min = 0;
UINT64 arr[MAX] = {0, };

void getMinVal(char *num, int n, int index) {
    int i = 0;
    if (index > maxIndex) {
        return;
    }

    if (!*num) {
        UINT64 v = 0, pow = 1;
        for (i=index-1;i>=0;i--) {
            v += arr[i] * pow;
            pow *= n;
        }

        if (min == 0 || min > v) {
            min = v;
        }
    } else {
        int v = 0;
        char sub[MAX] = {0, }, *p = num;

        while (*p) {
            if (p == num && *p == '0') {
                arr[index] = 0;
                getMinVal(p + 1, n, index + 1);
                break;
            } else {
                sub[i++] = *p;
                v = atoi(sub);
                if (v >= n) {
                    break;
                }

                arr[index] = v;
                p++;
                getMinVal(p, n, index + 1);
            }
        }
    }
}

void setMaxIndex(int n) {
    UINT64 v = MAX_VALUE;
    while (v) {
        v /= n;
        maxIndex++;
    }
}

int main(void) {
    int n = 0;
    char num[MAX] = {0, };

    scanf("%d", &n);
    scanf("%s", num);

    setMaxIndex(n);
    getMinVal(num, n, 0);

    printf("%llu\n", min);

    return 0;
}

