#define M	4167669	/* (23 choose 7) * 17 */
#define C	16
#define K	2000000000
#define T	7

int add(int a, int b) { return (long long) a + b < K ? a + b : K; }

void print(int k) {
	if (k == 0)
		return;
	print(k / C);
	printf("%c", k % C < 10 ? k % C + '0' : k % C - 10 + 'a');
}

int aaa[M][C + 1], m;

void branch(int *aa, int h) {
	int a, len;

	if (h == C) {
		for (len = 0; len <= C; len++) {
			aa[h] = len;
			memcpy(aaa[m++], aa, (C + 1) * sizeof *aa);
		}
		return;
	}
	for (a = h == 0 ? 0 : aa[h - 1]; a <= T; a++) {
		aa[h] = a;
		branch(aa, h + 1);
	}
}

int choose[C + T][C + T];

void init1() {
	int n, r;

	choose[0][0] = 1;
	for (n = 1; n < C + T; n++) {
		choose[n][0] = 1;
		for (r = 1; r <= n; r++)
			choose[n][r] = choose[n - 1][r - 1] + choose[n - 1][r];
	}
}

int idx(int *aa) {
	int h, a, sum;

	sum = 0;
	for (h = 0; h < C; h++)
		for (a = h == 0 ? 0 : aa[h - 1]; a < aa[h]; a++)
			sum += choose[C - h - 1 + T - a][T - a];
	return sum * (C + 1) + aa[C];
}

int dp[M];

void init2() {
	static int a_[C + 1], *aa = a_;
	int h, i, j, a, len;

	branch(aa, 0);
	for (i = 0; i < m; i++) {
		aa = aaa[i];
		len = aa[C];
		if (len == 0)
			dp[i] = 1;
		else
			for (h = 0; h < C; h++) {
				if (aa[h] == 0)
					continue;
				if (h == 0 || aa[h - 1] != aa[h]) {
					a = aa[h] - 1;
					j = i / (C + 1) - choose[C - h - 1 + T - a][T - a];
					if (h < C - 1)
						j += choose[C - h - 2 + T - a][T - a];
					j = j * (C + 1) + len - 1;
				}
				dp[i] = add(dp[i], dp[j]);
			}
	}
}

int compare(const void *a, const void *b) {
	int ia = *(int *) a;
	int ib = *(int *) b;

	return ia - ib;
}

int main() {
	static int aa[C + 1], bb[C + 1];
	int k, t, h, i, first;

	scanf("%d%d", &k, &t);
	if (t >= 8) {
		print(k);
		printf("\n");
		return 0;
	}
	init1();
	init2();
	for (h = 0; h < C; h++)
		aa[h] = t;
	for (aa[C] = 1; ; aa[C]++) {
		int cnt = dp[idx(aa)];

		aa[0]--; aa[C]--;
		cnt -= dp[idx(aa)];
		aa[0]++; aa[C]++;
		if (k <= cnt)
			break;
		k -= cnt;
	}
	first = 1;
	while (aa[C]-- > 0) {
		for (h = first ? 1 : 0; h < C; h++) {
			memcpy(bb, aa, (C + 1) * sizeof *aa);
			if (bb[h] == 0)
				continue;
			bb[h]--;
			qsort(bb, C, sizeof *bb, compare);
			if (k > dp[i = idx(bb)]) {
				k -= dp[i];
				bb[h]++;
			} else {
				printf("%c", h < 10 ? h + '0' : h - 10 + 'a');
				aa[h]--;
				break;
			}
		}
		first = 0;
	}
	printf("\n");
	return 0;
}

