#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

int odd_goldbach(int *prime, int n) {
    int i;
    for (i = 2; i <= n-i; i++) {
        if (prime[i] && prime[n-i]) {
            return 1;
        }
    }
    return 0;
}

int main(void) {
    int n, *prime, i, j;
    scanf("%d",&n);
    prime = (int*)malloc(sizeof(int)*(n+1));
    assert(prime);
    for (i = 2; i <= n; i++) {
        prime[i] = 1;
    }
    for (i = 2; i <= n; i++) {
        for (j = 2; prime[i] && i*j <= n; j++) {
            prime[i*j] = 0;
        }
    }
    if (prime[n]) {
        putchar('1');
    } else if (!(n%2) || odd_goldbach(prime,n)) {
        putchar('2');
    } else {
        putchar('3');
    }
    free(prime);
    return 0;
}

