long long dpp[5002][5002];
int n , a , b , k ;

#define MOD 1000000007

void build(long long arr[] , long long rmq []){
	int i ;
	for(i = 1 ; i <= n ; i++){
		// cout << arr[i] << " " ;
		int index = i ;
		while(index <= n){
			rmq[index] += arr[i] ;
			index += (index & -index);
		}
	}
	//cout << endl ;
}

long long query(long long rmq [] , int to){
	long long ret = 0 ;
	// cout << "to : " << to << " : "  ;
	while(to > 0){
		ret += rmq[to];
		ret %= MOD ;
		to -= (to & -to);
	}
	//cout <<ret << endl ;
	return ret ;
}

int main(){
	scanf("%d%d%d%d" , & n , &a , &b , &k);
	int i ;
	for(i = 1 ; i <= n ; i ++){
		dpp[0][i] = 1 ;
	}
	dpp[0][b] = 0 ;
	for(i =  1 ; i <= k ; i++){
		// cout << i << " : " << endl ;
		long long rmq [10003] ={0};
		build(dpp[i-1] , rmq);
		int j ;
		for(j = 1 ; j <= n; j++){
			if(j == b)
				continue ;
			int diff = abs(b - j) - 1;
			dpp[i][j] = query(rmq , min(n , j + diff));
			dpp[i][j] -= query(rmq , max(1 , j - diff) -1 );
			dpp[i][j] -= dpp[i-1][j];
			dpp[i][j] %= MOD ;
			dpp[i][j] += MOD ;
			dpp[i][j] %= MOD ;
		}
		// cout << i << " :  => " << endl ;
		// for(int j = 1 ; j <= n ; j++){
		// 	cout << dpp[i][j] << " ";
		// }
		//cout << endl ;
	}
	printf("%d" , dpp[k][a]);
	return 0 ;
}

