int k[20];

__int64 P(__int64 n){
    memset(k,0,sizeof(k));
    int i,j;
    i=0;
    while(n){
        k[i++]=n%10;
        n/=10;
    }
    int m=i-1;
    for(i=m;i>=0;i--){
        if(k[i]>7){
            for(j=i;j<=m;j++){
                if(k[j]>7){
                    k[j+1]=k[j+1]+1;
                    if(j+1>m)
                        m=j+1;
                    k[j]=0;
                }
            }
            break;
        }
    }
    __int64 sum=0;
    for(i=m;i>=0;i--){
        if(k[i]<4){
            sum=sum*10+4;
            for(j=i-1;j>=0;j--){
                sum=sum*10+4;
            }
            break;
        }
        else if(k[i]==4){
            sum=sum*10+4;
        }
        else if(k[i]<7){
            sum=sum*10+7;
            for(j=i-1;j>=0;j--){
                sum=sum*10+4;
            }
            break;
        }
        else if(k[i]==7){
            sum=sum*10+7;
        }
    }
    return sum;
}

int main(void){
    __int64 i,x,y,sum,k;
    scanf("%I64d %I64d",&x,&y);
    sum=0;
    k=0;
    for(i=x;i<=y;i++){
        if(k<i){
            k=P(i);
        }
        sum+=k;
    }
    printf("%I64d\n",sum);
    return 0;
}

