#define INF	0x3f3f3f3f

int min(int a, int b) { return a < b ? a : b; }

void carry(int *aa, int n) {
	int i;

	for (i = 0; i < n; i++)
		if (aa[i] >= 10)
			aa[i + 1] += aa[i] / 10, aa[i] %= 10;
		else if (aa[i] < 0)
			aa[i + 1] -= (-aa[i] + 9) / 10, aa[i] = (aa[i] % 10 + 10) % 10;
}

int main() {
	static char aa[N + 1];
	static int bb[N + 1], dp[K * 2 + 1], dq[K * 2 + 1], dp_[K * 2 + 1], dq_[K * 2 + 1];
