#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define maxN 65

char str[maxN];
char tmpstr[maxN];
char tgt[maxN];

int zeroCnt(char *str) {
    int ctr = 0;
    for (int i = strlen(str) - 1; i >= 0; --i) {
        if (str[i] == '0') ++ctr;
    }
    return ctr;
}

void trim(char *str) {
    for (int i = strlen(str) - 1; i >= 0; --i) {
        if (str[i] == '1') break;
        else str[i] = '\0';
    }
}

static inline void cswap(char *a, char *b) {
    char tmp = *a;
    *a = *b;
    *b = tmp;
    return;
}

void reverse(char *str) {
    int p = 0, q = strlen(str) - 1;
    for (; p < q; ++p, --q) {
        cswap(&str[p], &str[q]);
    }
}

// bin
#define lltoa(a, b) _lltoa(a, b)
void _lltoa(long long num, char *dest) {
    int len = 0;
    while (num) {
        if (num % 2 == 0) dest[len++] = '0';
        else dest[len++] = '1';
        num /= 2;
    }
    dest[len] = '\0';
    reverse(dest);
}

void testcase() {
    long long a, b;
    scanf("%lld%lld", &a, &b);
    lltoa(a, str);
    lltoa(b, tgt);
    // Orig string: Either equal, or at least a 1 on the right, and any amount of 1s on the left and right after.
    if (strcmp(tgt, str) == 0) { printf("YES\n"); return; }
    // Make sure at least one 1 is on the right.
    strcpy(tmpstr, str);
    int len = strlen(tmpstr);
    if (tmpstr[len - 1] == '0') {
        tmpstr[len++] = '1';
        tmpstr[len] = '\0';
    }
    if (strstr(tgt, tmpstr) && zeroCnt(tgt) == zeroCnt(tmpstr)) { printf("YES\n"); return; }

    // 2 flips performed: Completely trimmed. Add any amount of 1s to the left or right.
    trim(str);
    if (strstr(tgt, str) && zeroCnt(tgt) == zeroCnt(str)) { printf("YES\n"); return; }
    
    // 1 flip performed. Both sides start and end with a 1. Add any amounts of 1 left and right.
    reverse(str);
    trim(str);
    if (strstr(tgt, str) && zeroCnt(tgt) == zeroCnt(str)) { printf("YES\n"); return; }
    printf("NO\n");

    return;
}

int main() {
    testcase();
    return 0;
}

