int func (long long x, int n, int ans, int num, long long *pow10, long long *pow9) {
  int cnt = 0;
  int digit[10] = {};

  long long tmp = x;

  while (tmp > 0LL) {
    digit[(int)(tmp%10LL)] = 1;
    tmp /= 10LL;
    cnt++;
  }

  if (cnt > n) {
    return 100;
  }

  if (cnt == n) {
    return num;
  }

  for (int i = 9; i > 1; i--) {
    if (digit[i] > 0) {
      long long nx = x*((long long)i);
      if (ans-num-1 > 17 || (pow10[n-1]-1LL)/pow9[ans-num-1] < nx) {
        int tmp = func(nx, n, ans, num+1, pow10, pow9);
        if (tmp < ans) {
          ans = tmp;
        }
      }
    }
  }

  return ans;
}

