  for (int i = 1; i <= n; i++) {
    pow10[i] = 10LL*pow10[i-1];
  }

  pow9[0] = 1LL;
  for (int i = 1; i < 19; i++) {
    pow9[i] = 9LL*pow9[i-1];
  }

