void init()
{
	memset(cur,0,sizeof(cur));
	fc[0]=1LL;
	for(int i=1;i<2000000;i++)
	fc[i]=fc[i-1]*i%mod;
	for(int i=0;i<2000000;i++)
	inv[i]=f(fc[i],mod-2);
	for(int i=1;i<=1000000;i++)
	vv[i]=i;
	cur[1]=1;
	for(int i=2;i<=1000000;i++)
	{
		if(!cur[i])
		{
			v[i].push_back(1);
			for(int j=i+i;j<=1000000;j+=i)
			{
				cur[j]=1;
				int q=0;
				while(vv[j]%i==0)
				{
					q++;
					vv[j]/=i;
				}
				v[j].push_back(q);
			}
		}
	}
}
long long f(long long a,long long b)
{
	long long c=1;
	while(b)
	{
		if(b&1)
		{
			c*=a;
			c%=mod;
		}
		a*=a;
		a%=mod;
		b>>=1;
	}
	return c;
}
