int square(int n)
{
    int i=1;
    int sum=0;
    while(i*i<n)
    {
       sum=sum+1;
      i++;
    }
    return sum;
}
int cube(int n)
{
    int i=1;
    int sum=0;
    while(i*i*i<n)
    {
        sum=sum+1;
        i++;
    }
    return sum;
}
int sqrcube(int n)
{
    int i=1;
    int sum=0;
    while(i*i*i<n)
    {
        for(long int j=1;j<=i*i;j++)
        {
            if(j*j == i*i*i)
            {
                 sum = sum + 1;
            }
        }
        i++;
    }
    return sum;
}
