uint64_t number(uint64_t input){
  if(input==1 && input==2) return 1;
  uint64_t sl,cl,red=0;
  for(uint64_t i=2; i<input; i++){
    if(i*i == input) {sl=i; break;}
    if(i*i > input) {sl=i-1; break;}
  }
  for(uint64_t i=2; i<input; i++){
    if(i*i*i == input) {cl=i; break;}
    if(i*i*i > input) {cl=i-1; break;}
  }
  for(uint64_t i=1; i<=cl; i++){
    for(uint64_t j=1; j<=sl; j++){
      if(i*i*i == j*j) red++;
    }
  }
  return sl+cl-red;
}

