initFacs() {
	fac[0] = 1;
    for (int i = 1; i <= maxN; i++) fac[i] = fac[i - 1] * i % MOD; 
}

// Calculate base ^ pow % mod
long long modPower(long long base, int pow, int mod)
{
    long long res = 1;
    base %= mod;
    // constantly decompose base ^ pow = (base ^ 2) ^ (pow / 2)
    while (pow > 0) {
        // make sure if it is odd, then base ^ pow = base ^ (pow - 1) * base
        if (pow % 2 == 1) res = res * base % mod;
        pow /= 2;
        base = (base * base) % mod;
    }
    return res;
}

// a ^ (p - 2) = a ^ (-1) (mod p)
long long modInverse(long long n, int mod) {
    return modPower(n, mod - 2, mod);
}

// nCr = n! / r! / (n - r)!
// nCr = n! * inv(r!) * inv((n - r)!)
long long nCrModP(unsigned long long n, int r, int mod) {
    // Base cases
    if (n < r) return 0;
    if (r == 0) return 1;

    return fac[n] * modInverse(fac[r], mod) % mod
           * modInverse(fac[n - r], mod) % mod;
}
// END MODULAR NCR

void testcase() {
	int n, k;
	scanf("%d%d", &n, &k);
	long long T;
	long long ans;
	if (n % 2 == 1) {
		// n odd
		T = 1;
		for (int i = 0; i <= (n - 1) / 2; ++i) {
			T += nCrModP(n, i, MOD);
			T %= MOD;
		}
		ans = 1;
		for (int i = 0; i < k; ++i) {
			ans *= T;
			ans %= MOD;
		}
	} else {
		// n even
		T = 0;
		for (int i = 0; i < n / 2; ++i) {
			T += nCrModP(n, 2 * i, MOD);
			T %= MOD;
		}
		if (T == 1) {
			ans = k + 1;
		} else {
			// GP, T != 1
			ans = modPower(T, k + 1, MOD);
			ans -= 1;
			ans *= modInverse(T - 1, MOD);
			ans %= MOD;
		}
	}
	printf("%lld\n", ans);
    return;
}

int main() {
    int t;
    scanf("%d", &t);
    for (int i = 0; i < t; ++i) testcase();
    return 0;
}

