int winning (int n, int k) {
  if (k == 0) {
    return 1;
  }
  if (n % 2 == 0) {
    long long int result = expmod(2, n*(k-1), mod) + (expmod(2, n-1, mod)-1)*winning(n, k-1);
    return result % mod;
  }
  else {
    long long int result = (expmod(2, n-1, mod)+1)*winning(n, k-1);
    return result % mod;
  }
}

int expmod(long long int a, int b, int m)
{
	int res = 1;
	a = a % m; 

	if (a == 0) return 0;

	while (b > 0)
	{
		if (b & 1)
			res = (res*a) % m;

		b = b>>1;
		a = (a*a) % m;
	}
	return res;
}

