#define N	100
#define M	100

int main() {
	int t;

	scanf("%d", &t);
	while (t--) {
		static char cc[N][M + 1], cc_[M][N + 1];
		int n, m, k, i, j, tmp, flip;

		scanf("%d%d%d", &n, &m, &k);
		flip = 0;
		if (n % 2 != 0)
			tmp = n, n = m, m = tmp, k = n * m / 2 - k, flip = 1;
		if (k % 2 != 0 || m % 2 != 0 && k > n * (m - 1) / 2) {
			printf("NO\n");
			continue;
		}
		for (i = 0; i < n; i++)
			for (j = 0; j < m; j++)
				cc[i][j] = (i / 2 + j) % 2 == 0 ? 'a' : 'b';
		for (i = 0; i < n; i += 2)
			for (j = 0; j + 1 < m; j += 2)
				if (k > 0) {
					k -= 2;
					if ((j / 2) % 2 == 0) {
						cc[i][j] = 'c', cc[i][j + 1] = 'c';
						cc[i + 1][j] = 'd', cc[i + 1][j + 1] = 'd';
					} else {
						cc[i][j] = 'd', cc[i][j + 1] = 'd';
						cc[i + 1][j] = 'c', cc[i + 1][j + 1] = 'c';
					}
				}
		if (flip) {
			for (i = 0; i < n; i++)
				for (j = 0; j < m; j++)
					cc_[j][i] = cc[i][j];
			for (i = 0; i < m; i++)
				for (j = 0; j < n; j++)
					cc[i][j] = cc_[i][j];
			tmp = n, n = m, m = tmp;
		}
		for (i = 0; i < n; i++)
			cc[i][m] = 0;
		printf("YES\n");
		for (i = 0; i < n; i++)
			printf("%s\n", cc[i]);
	}
	return 0;
}

#include <stdio.h>
