int	getmin(int a, int b)
{
	if (a < b)
		return (a);
	return (b);
}
int	getmax(int a, int b)
{
	if (a > b)
		return (a);
	return (b);
}

int	*get_tab(int *c, int size)
{
	int	*t;
	int	i;
	int	j;

	i = 0;
	j = 0;
	t = (int *)malloc (sizeof(int) * size);
	while (i < size)
	{
		if ((c[j] + c[j + 1]) % 2 == 0)
			t[i] = getmax(c[j], c[j + 1]);
		else
			t[i] = getmin(c[j], c[j + 1]);

		j += 2;
		i++;
	}
	return (t);
}

int	pow_t(int a, int b)
{
	int	i;

	i = 1;
	while (i < b)
	{	
		a = a * 2;
		i++;
	}
	return (a);
}

int main()
{
	int	t;
	int	cas;
	int	i;
	int	j;
	int	size;
	int	k;
	int	*tab;
	int	*tmp;
	int	arr;


	scanf("%d",&t);
	int	n[t];
	i = 0;
	while (i < t)
	{
		scanf("%d",&n[i]);
		i++;
	}
	cas = 0;
	while (cas < t)
	{
		if (n[cas] == 1)
			printf("1\n");
		else
		{
			arr = pow_t(2, n[cas]);
			tab = (int *)malloc(sizeof(int) * arr / 2);
			i = 1;
			j = 0;
			while (i < arr)
			{
				if ((i + i + 1) % 2 == 0)
					tab[j] = getmax(i, i + 1);
				else
					tab[j] = getmin(i, i + 1);
				i = i + 2;
				j++;
			}
			size = arr / 2;
			k = 1;
			while ((k < n[cas]))
			{
				size /= 2;
				tmp = tab;
				tab = get_tab(tab, size);
				free(tmp);
				k++;
			}
			free(tab);
			if ((tab[0] + tab[1]) % 2 == 0)
				printf("%d\n",getmax(tab[0], tab[1]));
			else
				printf("%d\n",getmin(tab[0], tab[1]));
		}
		cas ++;
	}
