}

int winner(int stages)
{
    int player_num = 1 << stages;
    int *players = (int *)malloc(player_num * sizeof(int));
    for (int i = 0; i < player_num; i++) {
        players[i] = i + 1;
    }
    for (int i = player_num / 2; i != 0; i = i / 2) {
        for (int j = 0; j < i; j++) {
            players[j] = ((players[2 * j + 1] + players[2 * j]) % 2)? players[2 * j] : players[2 * j + 1];
        }
    }
    free(players);
    return players[0];
}

